            ttk.Label(ma5_price_row, text="前5日均价:", width=10).pack(side=tk.LEFT)
            ttk.Label(ma5_price_row, textvariable=ma5_prev_var, foreground="green").pack(side=tk.LEFT)

            ma5_status_row = ttk.Frame(ma5_frame)
