    def _apply_ths_sentiment_trend_to_checkboxes(self, trend):
        """将 上行/震荡/下行 映射到开新仓流程中的两个勾选框。"""
        try:
            if trend == "上行":
                self.sentiment_index_ma1_uptrend_var.set(True)
                self.sentiment_index_ma1_above_var.set(True)
            elif trend == "下行":
                self.sentiment_index_ma1_uptrend_var.set(False)
                self.sentiment_index_ma1_above_var.set(False)
            else:
                # 震荡:未明确向上,但仍可能在 1 日线上 → 不满足「双勾选」开新仓条件
                self.sentiment_index_ma1_uptrend_var.set(False)
                self.sentiment_index_ma1_above_var.set(True)
            self._update_sentiment_index_check_coord()
        except Exception:
            pass

    def _update_sentiment_index_check_coord(self):
        """两个手动勾选框与「已确认」汇总状态同步。"""
        try:
            if self.sentiment_index_ma1_uptrend_var.get() and self.sentiment_index_ma1_above_var.get():
                self.sentiment_index_check_var.set(True)
            else:
                self.sentiment_index_check_var.set(False)
        except Exception:
            pass

    def _save_ths_sentiment_trend(self, trend):
        if trend not in ("上行", "震荡", "下行"):
            return
        self.ths_sentiment_trend_var.set(trend)
        self.ai_config_manager.config["ths_sentiment_trend"] = trend
        try:
            self.ai_config_manager.save_config()
        except Exception:
            pass
        self._apply_ths_sentiment_trend_to_checkboxes(trend)

    def _th_reminder_tick(self):
        """每半小时弹出一次:请选择同花顺情绪指数方向。"""
        try:
            if self.root.winfo_exists():
                self._show_ths_sentiment_reminder_dialog()
        except Exception:
            pass
        try:
            self.root.after(30 * 60 * 1000, self._th_reminder_tick)
        except Exception:
            pass

    def _show_ths_sentiment_reminder_dialog(self):
        top = tk.Toplevel(self.root)
        top.title("同花顺情绪指数")
        try:
            top.transient(self.root)
            top.grab_set()
        except Exception:
            pass
        top.geometry("440x210")
        f = ttk.Frame(top, padding=16)
        f.pack(fill=tk.BOTH, expand=True)
        ttk.Label(
            f,
            text="请选择当前同花顺情绪指数的大致方向(将与「交易」开新仓流程中的「1日线往上」「在1日线上」勾选框联动):",
            wraplength=400,
        ).pack(anchor=tk.W)
        var = tk.StringVar(value=self.ths_sentiment_trend_var.get())
        rb = ttk.Frame(f)
        rb.pack(anchor=tk.W, pady=(14, 10))
        for t in ("上行", "震荡", "下行"):
            ttk.Radiobutton(rb, text=t, variable=var, value=t).pack(side=tk.LEFT, padx=(0, 18))

        def on_ok():
            self._save_ths_sentiment_trend(var.get())
            top.destroy()

        bf = ttk.Frame(f)
        bf.pack(anchor=tk.E, pady=(6, 0))
        ttk.Button(bf, text="确定", command=on_ok, width=10).pack(side=tk.RIGHT, padx=(6, 0))
        ttk.Button(bf, text="稍后", command=top.destroy, width=10).pack(side=tk.RIGHT)
        top.protocol("WM_DELETE_WINDOW", top.destroy)
        try:
            top.lift()
            top.attributes("-topmost", True)
            top.after(300, lambda: top.attributes("-topmost", False))
            top.focus_force()
        except Exception:
            pass

    def _create_market_indices_tab_in_notebook(self, notebook):
        """在market_notebook中创建市场指数标签页(仅创建框架,内容由_create_market_indices_tab填充)"""
        # 检查标签页是否已存在
        for i in range(notebook.index("end")):
            if notebook.tab(i, "text") == "市场指数":
                return  # 已存在,不重复创建

        # 创建新标签页
        tab_frame = ttk.Frame(notebook, padding=10)
        # 如果notebook为空,使用add;否则使用insert插入到第一个位置
        if notebook.index("end") == 0:
            notebook.add(tab_frame, text="市场指数")
        else:
            notebook.insert(0, tab_frame, text="市场指数")  # 插入到第一个位置(宏观指数之前)
        # 保存引用,供后续填充内容
        self.market_notebook = notebook

    def _create_market_indices_tab(self):
        """创建市场指数标签页(在market_notebook中)"""
        if not hasattr(self, 'market_notebook') or not self.market_notebook:
            return

        # 检查标签页是否已存在
        existing_index = None
        for i in range(self.market_notebook.index("end")):
            if self.market_notebook.tab(i, "text") == "市场指数":
                existing_index = i
                break

        if existing_index is None:
            # 创建新标签页
            tab_frame = ttk.Frame(self.market_notebook, padding=10)
            self.market_notebook.insert(0, tab_frame, text="市场指数")
        else:
            # 获取现有标签页
            tab_frame = self.market_notebook.nametowidget(self.market_notebook.tabs()[existing_index])
            # 清空内容
            for widget in tab_frame.winfo_children():
                widget.destroy()

        # 继续创建内容
        # 清空原有的文本框
        for widget in tab_frame.winfo_children():
            if isinstance(widget, tk.Text):
                widget.destroy()
            elif isinstance(widget, ttk.Frame) and widget.winfo_children():
                # 检查是否是工具栏
                for child in widget.winfo_children():
                    if isinstance(child, ttk.Button) and child.cget("text") == "×":
                        continue
                    widget.destroy()

        # 创建滚动框架
        canvas_frame = ttk.Frame(tab_frame)
        canvas_frame.pack(fill=tk.BOTH, expand=True)

        canvas = tk.Canvas(canvas_frame)
        scrollbar = ttk.Scrollbar(canvas_frame, orient=tk.VERTICAL, command=canvas.yview)
        scrollable_frame = ttk.Frame(canvas)

        scrollable_frame.bind(
            "<Configure>",
            lambda e: canvas.configure(scrollregion=canvas.bbox("all"))
        )

        canvas.create_window((0, 0), window=scrollable_frame, anchor="nw")
        canvas.configure(yscrollcommand=scrollbar.set)

        # 获取市场指数数据
        indices_data = self.market_nav_config.get("indices", [])

        # 确保每个项目都有排序字段
        for item in indices_data:
            if "sort_order" not in item:
                item["sort_order"] = len(indices_data)

        # 按排序字段排序
        indices_data = sorted(indices_data, key=lambda x: x.get("sort_order", 999))

        # 创建链接按钮
        for idx, item in enumerate(indices_data):
            name = item.get("name", "")
            url = item.get("url", "")
            sort_order = item.get("sort_order", idx + 1)

            # 判断是否为排名/热榜类按钮(包含"榜"、"排名"、"热"等关键词)
            is_rank_hot = any(keyword in name for keyword in ["榜", "排名", "热", "排行", "统计", "明细", "天梯"])

            # 根据排序和类型设置字体大小和颜色
            if is_rank_hot:
                # 排名和热榜类按钮:红色、橘黄色,加大加粗
                if sort_order == 1:
                    font_size = 18
                    bg_color = "red"
                    fg_color = "white"
                elif sort_order == 2:
                    font_size = 16
                    bg_color = "orange"
                    fg_color = "white"
                else:
                    font_size = 14
                    bg_color = "#FF6B35"  # 橘红色
                    fg_color = "white"
            else:
                # 普通按钮:根据排序设置
                if sort_order == 1:
                    font_size = 18
                    bg_color = "red"
                    fg_color = "white"
                elif sort_order == 2:
                    font_size = 16
                    bg_color = "orange"
                    fg_color = "white"
                elif sort_order == 3:
                    font_size = 14
                    bg_color = "blue"
                    fg_color = "white"
                else:
                    font_size = 12
                    bg_color = "lightgray"
                    fg_color = "black"

            # 创建链接按钮(纯按钮,无说明文字)
            def open_link(u=url, n=name):
                import webbrowser
                if u:
                    webbrowser.open(u)
                    # 复制链接到剪贴板
                    self.root.clipboard_clear()
                    self.root.clipboard_append(u)
                    self.root.update()
                else:
                    messagebox.showwarning("提示", f"按钮 '{n}' 的链接未配置")

            link_btn = tk.Button(
                scrollable_frame,
                text=name,
                font=("TkDefaultFont", font_size, "bold" if is_rank_hot or sort_order <= 3 else "normal"),
                bg=bg_color,
                fg=fg_color,
                cursor="hand2",
                relief=tk.RAISED,
                bd=2,
                padx=10,
                pady=5,
                command=lambda u=url, n=name: open_link(u, n)
            )
            link_btn.pack(fill=tk.X, padx=5, pady=3)

        canvas.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        scrollbar.pack(side=tk.RIGHT, fill=tk.Y)

        # 添加编辑按钮
        edit_frame = ttk.Frame(tab_frame)
        edit_frame.pack(fill=tk.X, padx=5, pady=5)
        ttk.Button(edit_frame, text="编辑排序", command=self._edit_market_indices_sort).pack(side=tk.LEFT, padx=5)

    def _create_hot_navigation_tab_in_notebook(self, notebook):
        """在market_notebook中创建热点导航标签页(仅创建框架,内容由_create_hot_navigation_tab填充)"""
        # 检查标签页是否已存在
        for i in range(notebook.index("end")):
            if notebook.tab(i, "text") == "热点导航":
                return  # 已存在,不重复创建

        # 创建新标签页
        tab_frame = ttk.Frame(notebook, padding=10)
        # 找到"市场指数"标签页的位置,在其后插入
        market_indices_index = None
        for i in range(notebook.index("end")):
            if notebook.tab(i, "text") == "市场指数":
                market_indices_index = i
                break
        if market_indices_index is not None:
            # 检查插入位置是否在有效范围内
            insert_pos = market_indices_index + 1
            if insert_pos < notebook.index("end"):
                notebook.insert(insert_pos, tab_frame, text="热点导航")
            else:
                # 如果插入位置超出范围,使用add添加到末尾
                notebook.add(tab_frame, text="热点导航")
        else:
            # 如果notebook为空,使用add;否则使用insert
            if notebook.index("end") == 0:
                notebook.add(tab_frame, text="热点导航")
            else:
                notebook.insert(0, tab_frame, text="热点导航")
        # 保存引用,供后续填充内容
        self.market_notebook = notebook

