    def _create_merged_market_hot_tab(self):
        """创建合并的市场指数&热点导航标签页(二列布局)"""
        if not hasattr(self, 'market_notebook') or not self.market_notebook:
            return

        # 检查标签页是否已存在
        existing_index = None
        for i in range(self.market_notebook.index("end")):
            if self.market_notebook.tab(i, "text") == "市场指数&热点导航":
                existing_index = i
                break

        if existing_index is None:
            # 创建新标签页
            tab_frame = ttk.Frame(self.market_notebook, padding=10)
            # 如果notebook为空,使用add;否则使用insert插入到第一个位置
            if self.market_notebook.index("end") == 0:
                self.market_notebook.add(tab_frame, text="市场指数&热点导航")
            else:
                self.market_notebook.insert(0, tab_frame, text="市场指数&热点导航")
        else:
            # 获取现有标签页
            tab_frame = self.market_notebook.nametowidget(self.market_notebook.tabs()[existing_index])
            # 清空内容
            for widget in tab_frame.winfo_children():
                widget.destroy()

        # 创建滚动框架
        canvas_frame = ttk.Frame(tab_frame)
        canvas_frame.pack(fill=tk.BOTH, expand=True)

        canvas = tk.Canvas(canvas_frame)
        scrollbar = ttk.Scrollbar(canvas_frame, orient=tk.VERTICAL, command=canvas.yview)
        scrollable_frame = ttk.Frame(canvas)

        scrollable_frame.bind(
            "<Configure>",
            lambda e: canvas.configure(scrollregion=canvas.bbox("all"))
        )

        canvas.create_window((0, 0), window=scrollable_frame, anchor="nw")
        canvas.configure(yscrollcommand=scrollbar.set)

        # 创建三列网格布局框架
        grid_frame = ttk.Frame(scrollable_frame)
        grid_frame.pack(fill=tk.BOTH, expand=True, padx=5, pady=5)

        # 配置三列,每列权重相等
        for col in range(3):
            grid_frame.columnconfigure(col, weight=1, uniform="equal")

        # 获取市场指数数据(创建副本,避免修改原始数据)
        indices_data = [item.copy() for item in self.market_nav_config.get("indices", [])]
        # 为市场指数数据添加类型标记
        for item in indices_data:
            item["_type"] = "indices"

        # 获取热点导航数据(portals和hot_sources)(创建副本)
        portals = [item.copy() for item in self.market_nav_config.get("portals", [])]
        hot_sources = [item.copy() for item in self.market_nav_config.get("hot_sources", [])]
        # 为热点导航数据添加类型标记
        for item in portals:
            item["_type"] = "portals"
        for item in hot_sources:
            item["_type"] = "hot_sources"

        # 合并所有数据
        all_data = indices_data + portals + hot_sources

        # 确保每个项目都有排序字段
        for item in all_data:
            if "sort_order" not in item:
                item["sort_order"] = len(all_data)

        # 按排序字段排序
        all_data = sorted(all_data, key=lambda x: x.get("sort_order", 999))

        # 存储按钮引用,用于拖拽
        button_refs = []

        # 创建按钮(三列布局,由上到下,由左到右)
        for idx, item in enumerate(all_data):
            name = item.get("name", "")
            url = item.get("url", "")
            sort_order = item.get("sort_order", idx + 1)
            item_type = item.get("_type", "")

            # 判断是否为排名/热榜类按钮
            is_rank_hot = any(keyword in name for keyword in ["榜", "排名", "热", "排行", "统计", "明细", "天梯"])

            # 优先使用配置的颜色,否则根据排序和类型设置字体大小和颜色(保持原有大小)
            bg_color = item.get("bg_color", "")
            fg_color = item.get("fg_color", "")

            if not bg_color or not fg_color:
                # 如果没有配置颜色,使用默认逻辑
                if is_rank_hot:
                    if sort_order == 1:
                        font_size = 18
                        bg_color = bg_color or "red"
                        fg_color = fg_color or "white"
                    elif sort_order == 2:
                        font_size = 16
                        bg_color = bg_color or "orange"
                        fg_color = fg_color or "white"
                    else:
                        font_size = 14
                        bg_color = bg_color or "#FF6B35"
                        fg_color = fg_color or "white"
                else:
                    if sort_order == 1:
                        font_size = 18
                        bg_color = bg_color or "red"
                        fg_color = fg_color or "white"
                    elif sort_order == 2:
                        font_size = 16
                        bg_color = bg_color or "orange"
                        fg_color = fg_color or "white"
                    elif sort_order == 3:
                        font_size = 14
                        bg_color = bg_color or "blue"
                        fg_color = fg_color or "white"
                    else:
                        font_size = 12
                        bg_color = bg_color or "lightgray"
                        fg_color = fg_color or "black"
            else:
                # 如果配置了颜色,根据字体大小设置(如果没有配置字体大小,使用默认值)
                if is_rank_hot or sort_order <= 3:
                    font_size = item.get("font_size", 14)
                else:
                    font_size = item.get("font_size", 12)

            def open_link(u=url, n=name):
                import webbrowser
                if u:
                    webbrowser.open(u)
                    self.root.clipboard_clear()
                    self.root.clipboard_append(u)
                    self.root.update()
                else:
                    messagebox.showwarning("提示", f"按钮 '{n}' 的链接未配置")

            # 计算网格位置(三列布局)
            row = idx // 3
            col = idx % 3

            # 创建复选框和按钮的容器框架
            btn_frame = ttk.Frame(grid_frame)
            btn_frame.grid(row=row, column=col, padx=4, pady=3, sticky="ew")

            # 创建复选框,加载保存的状态
            checkbox_key = f"merged_{idx}"
            saved_state = self.market_nav_checkbox_states.get(checkbox_key, False)
            checkbox_var = tk.BooleanVar(value=saved_state)
            if not hasattr(self, 'market_nav_checkboxes'):
                self.market_nav_checkboxes = {}
            self.market_nav_checkboxes[checkbox_key] = {
                'var': checkbox_var,
                'name': name,
                'url': url,
                'config_key': item_type
            }
            checkbox = ttk.Checkbutton(btn_frame, variable=checkbox_var,
                                       command=lambda k=checkbox_key, v=checkbox_var: self._save_market_nav_checkbox_state(k, v.get()))
            checkbox.pack(side=tk.LEFT, padx=(0, 3))

            link_btn = tk.Button(
                btn_frame,
                text=name,
                font=("TkDefaultFont", font_size, "bold" if is_rank_hot or sort_order <= 3 else "normal"),
                bg=bg_color,
                fg=fg_color,
                cursor="hand2",
                relief=tk.RAISED,
                bd=2,
                padx=10,
                pady=5,
                command=lambda u=url, n=name: open_link(u, n)
            )
            link_btn.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)

            # 存储按钮信息用于拖拽(注意:现在按钮在btn_frame中)
            button_info = {
                "button": link_btn,
                "button_frame": btn_frame,  # 添加按钮框架引用
                "item": item,
                "row": row,
                "col": col,
                "index": idx
            }
            button_refs.append(button_info)

            # 实现拖拽功能
            def on_drag_start(event, btn_info=button_info):
                btn_info["drag_start_x"] = event.x
                btn_info["drag_start_y"] = event.y
                btn_info["drag_start_root_x"] = event.x_root
                btn_info["drag_start_root_y"] = event.y_root
                btn_info["dragging"] = False  # 初始为False,只有移动一定距离后才开始拖拽
                btn_info["drag_threshold"] = 5  # 拖拽阈值(像素)
                btn_info["original_row"] = btn_info["row"]
                btn_info["original_col"] = btn_info["col"]
                # 保存原始位置(使用button_frame)
                btn_info["original_x"] = btn_info["button_frame"].winfo_x()
                btn_info["original_y"] = btn_info["button_frame"].winfo_y()

            def on_drag_motion(event, btn_info=button_info):
                # 计算移动距离
                dx = abs(event.x_root - btn_info["drag_start_root_x"])
                dy = abs(event.y_root - btn_info["drag_start_root_y"])
                distance = (dx**2 + dy**2)**0.5

                # 如果移动距离超过阈值,开始拖拽
                if not btn_info.get("dragging", False) and distance > btn_info["drag_threshold"]:
                    btn_info["dragging"] = True
                    # 提升按钮框架到最上层(通过临时使用place)
                    btn_info["button_frame"].grid_remove()
                    btn_info["button_frame"].place(x=btn_info["original_x"], y=btn_info["original_y"])
                    btn_info["button_frame"].lift()

                if btn_info.get("dragging", False):
                    # 计算新位置(相对于原始位置)
                    new_x = btn_info["original_x"] + (event.x - btn_info["drag_start_x"])
                    new_y = btn_info["original_y"] + (event.y - btn_info["drag_start_y"])
                    # 限制在grid_frame范围内
                    frame_x = grid_frame.winfo_x()
                    frame_y = grid_frame.winfo_y()
                    frame_width = grid_frame.winfo_width()
                    frame_height = grid_frame.winfo_height()
                    btn_width = btn_info["button_frame"].winfo_width()
                    btn_height = btn_info["button_frame"].winfo_height()

                    # 限制在框架内
                    new_x = max(frame_x, min(new_x, frame_x + frame_width - btn_width))
                    new_y = max(frame_y, min(new_y, frame_y + frame_height - btn_height))

                    btn_info["button_frame"].place(x=new_x, y=new_y)

            def on_drag_end(event, btn_info=button_info):
                was_dragging = btn_info.get("dragging", False)
                btn_info["dragging"] = False

                if was_dragging:
                    # 计算新网格位置(相对于grid_frame)
                    btn_x = btn_info["button_frame"].winfo_x() - grid_frame.winfo_x()
                    btn_y = btn_info["button_frame"].winfo_y() - grid_frame.winfo_y()

                    # 计算目标行列
                    cell_width = grid_frame.winfo_width() // 3
                    # 估算行高(按钮框架高度 + padding)
                    btn_height = btn_info["button_frame"].winfo_height()
                    if btn_height == 1:  # 如果按钮框架还没渲染,使用估算值
                        btn_height = 50
                    cell_height = btn_height + 6  # 6是pady*2

                    target_col = min(2, max(0, int(btn_x / cell_width)))
                    target_row = max(0, int(btn_y / cell_height))
                    target_idx = target_row * 3 + target_col

                    # 限制在有效范围内
                    target_idx = min(len(button_refs) - 1, max(0, target_idx))

                    # 恢复grid布局
                    btn_info["button_frame"].place_forget()
                    btn_info["button_frame"].grid(row=btn_info["row"], column=btn_info["col"], padx=4, pady=3, sticky="ew")

                    # 如果位置改变,更新排序
                    if target_idx != btn_info["index"]:
                        # 重新排列按钮
                        self._reorder_buttons(button_refs, btn_info["index"], target_idx)
                else:
                    # 如果没有拖拽,只是点击,正常执行按钮的command
                    pass

            # 绑定拖拽事件
            link_btn.bind("<Button-1>", on_drag_start)
            link_btn.bind("<B1-Motion>", on_drag_motion)
            link_btn.bind("<ButtonRelease-1>", on_drag_end)

        canvas.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        scrollbar.pack(side=tk.RIGHT, fill=tk.Y)

        # 保存按钮引用到实例变量,供重新排列函数使用
        if not hasattr(self, '_merged_tab_button_refs'):
            self._merged_tab_button_refs = []
        self._merged_tab_button_refs = button_refs

        # 添加编辑按钮
        edit_frame = ttk.Frame(tab_frame)
        edit_frame.pack(fill=tk.X, padx=5, pady=5)
        # 编辑导航按钮(打开编辑导航窗口,可以编辑所有内容)
        ttk.Button(edit_frame, text="编辑导航", command=self.show_market_nav_editor).pack(side=tk.LEFT, padx=5)
        # 编辑市场指数按钮(打开编辑导航窗口并定位到市场指数标签页)
        ttk.Button(edit_frame, text="编辑市场指数", command=lambda: self.show_market_nav_editor(default_tab=0)).pack(side=tk.LEFT, padx=5)
        # 编辑热点导航按钮(打开编辑导航窗口,热点导航包含portals和hot_sources两个标签页)
        ttk.Button(edit_frame, text="编辑热点导航", command=lambda: self.show_market_nav_editor(default_tab=1)).pack(side=tk.LEFT, padx=5)
        # 排序按钮(仅编辑排序)
        ttk.Button(edit_frame, text="市场指数排序", command=self._edit_market_indices_sort).pack(side=tk.LEFT, padx=5)
        ttk.Button(edit_frame, text="热点导航排序", command=self._edit_hot_navigation_sort).pack(side=tk.LEFT, padx=5)
        # 设定为默认按钮(将当前配置保存为新的默认值)
        ttk.Button(edit_frame, text="设定为默认", command=self.set_merged_as_default_config).pack(side=tk.LEFT, padx=5)

        # 界面创建完成,立即显示窗口并强制刷新
        self.root.deiconify()  # 确保窗口可见
        self.root.update()
        self.root.update_idletasks()
        self.root.lift()  # 将窗口置于最前
        self.root.focus_force()  # 强制获得焦点

        # 延迟初始化耗时操作(在后台线程中执行,不阻塞界面)
        def delayed_init():
            try:
                # 初始化爬虫(可能耗时)
                if self.taoguba_crawler is None:
                    self.taoguba_crawler = TaogubaCrawler()
                if self.jiuyangongshe_crawler is None:
                    self.jiuyangongshe_crawler = JiuYangGongSheCrawler()

                # 加载配置文件(可能耗时)
                if not self.market_nav_config:
                    self.market_nav_config = self.load_market_nav_config()
                if not self.crawler_config:
                    self.crawler_config = self.load_crawler_config()

                # 加载管理的股票列表(可能耗时)
                self._load_managed_stocks_from_file()

                # 不自动启动持仓股振幅监控,等待用户手动开启预警开关
                # self._start_holding_amplitude_monitor()  # 已禁用,等待用户开启预警开关
            except Exception as e:
                print(f"延迟初始化失败: {e}")

        # 在界面显示后延迟执行耗时操作
        self.root.after(100, delayed_init)

    def set_merged_as_default_config(self):
        """将合并标签页的当前配置设定为默认值(更新配置文件)"""
        if messagebox.askyesno("确认", "确定要将当前【市场指数&热点导航】配置设定为新的默认值吗?\n\n这将更新配置文件,包括市场指数、财经/量化平台和热门榜单的配置。"):
            try:
                # 获取当前配置
                indices_data = self.market_nav_config.get("indices", [])
                portals_data = self.market_nav_config.get("portals", [])
                hot_sources_data = self.market_nav_config.get("hot_sources", [])

                # 清理数据(移除_type标记,但保留其他所有字段包括颜色)
                cleaned_indices = []
                for item in indices_data:
                    cleaned = {k: v for k, v in item.items() if k != "_type"}
                    if "sort_order" not in cleaned:
                        cleaned["sort_order"] = len(cleaned_indices) + 1
                    cleaned_indices.append(cleaned)

                cleaned_portals = []
                for item in portals_data:
                    cleaned = {k: v for k, v in item.items() if k != "_type"}
                    if "sort_order" not in cleaned:
                        cleaned["sort_order"] = len(cleaned_portals) + 1
                    cleaned_portals.append(cleaned)

                cleaned_hot_sources = []
                for item in hot_sources_data:
                    cleaned = {k: v for k, v in item.items() if k != "_type"}
                    if "sort_order" not in cleaned:
                        cleaned["sort_order"] = len(cleaned_hot_sources) + 1
                    cleaned_hot_sources.append(cleaned)

                # 更新当前配置(确保保存)
                self.market_nav_config["indices"] = cleaned_indices
                self.market_nav_config["portals"] = cleaned_portals
                self.market_nav_config["hot_sources"] = cleaned_hot_sources
                self.save_market_nav_config()

                # 同时保存为备份文件,方便查看
                import json
                backup_file = os.path.join(_APP_CONFIG_DIR, "market_nav_config_merged_default_backup.json")
                default_config = {
                    "indices": cleaned_indices,
                    "portals": cleaned_portals,
                    "hot_sources": cleaned_hot_sources,
                    "dv_accounts": self.market_nav_config.get("dv_accounts", [])
                }

                with open(backup_file, "w", encoding="utf-8") as f:
                    json.dump(default_config, f, ensure_ascii=False, indent=2)

                messagebox.showinfo("成功", f"当前【市场指数&热点导航】配置已设定为默认值并保存!\n\n备份文件:{backup_file}\n\n配置已保存到配置文件,下次启动程序时会自动加载。")
            except Exception as e:
                messagebox.showerror("错误", f"设定为默认失败: {e}")
                import traceback
                traceback.print_exc()

    def set_as_default_config(self, config_key):
        """将指定配置的当前内容设定为默认值(更新配置文件)"""
        config_name_map = {
            "indices": "宏观&指数",
            "portals": "财经/量化平台",
            "hot_sources": "热门榜单",
            "dv_accounts": "大V公众号"
        }
        config_name = config_name_map.get(config_key, config_key)

        if messagebox.askyesno("确认", f"确定要将当前【{config_name}】配置设定为新的默认值吗?\n\n这将更新配置文件,下次加载时会使用这些值作为默认配置。"):
            try:
                # 获取当前配置
                data_list = self.market_nav_config.get(config_key, [])

                if not data_list:
                    messagebox.showwarning("提示", f"当前{config_name}配置为空,无法设定为默认值。")
                    return

                # 清理数据(移除_type标记,但保留其他所有字段包括颜色)
                cleaned_data = []
                for item in data_list:
                    cleaned = {k: v for k, v in item.items() if k != "_type"}
                    # 确保有排序字段
                    if "sort_order" not in cleaned:
                        cleaned["sort_order"] = len(cleaned_data) + 1
                    cleaned_data.append(cleaned)

                # 更新当前配置(确保保存)
                self.market_nav_config[config_key] = cleaned_data
                self.save_market_nav_config()

                # 同时保存为备份文件,方便查看
                import json
                backup_file = os.path.join(_APP_CONFIG_DIR, f"market_nav_config_{config_key}_default_backup.json")
                with open(backup_file, "w", encoding="utf-8") as f:
                    json.dump(cleaned_data, f, ensure_ascii=False, indent=2)

                messagebox.showinfo("成功", f"当前【{config_name}】配置已设定为默认值并保存!\n\n备份文件:{backup_file}\n\n配置已保存到配置文件,下次启动程序时会自动加载。")
            except Exception as e:
                messagebox.showerror("错误", f"设定为默认失败: {e}")
                import traceback
                traceback.print_exc()

    def _create_draggable_button_grid(self, tab_frame, config_key, title_text):
        """创建可拖拽的三列按钮网格

        Args:
            tab_frame: 标签页框架
            config_key: 配置键("indices" 或 "dv_accounts")
            title_text: 标题文本
        """
        # 清空标签页内容
        for widget in tab_frame.winfo_children():
            widget.destroy()

        ttk.Label(tab_frame, text=title_text, font=("TkDefaultFont", 10, "bold")).pack(
            anchor="w", pady=(0, 6)
        )

        # 创建滚动框架
        canvas_frame = ttk.Frame(tab_frame)
        canvas_frame.pack(fill=tk.BOTH, expand=True)

        canvas = tk.Canvas(canvas_frame)
        scrollbar = ttk.Scrollbar(canvas_frame, orient=tk.VERTICAL, command=canvas.yview)
        scrollable_frame = ttk.Frame(canvas)

        scrollable_frame.bind(
            "<Configure>",
            lambda e: canvas.configure(scrollregion=canvas.bbox("all"))
        )

        canvas.create_window((0, 0), window=scrollable_frame, anchor="nw")
        canvas.configure(yscrollcommand=scrollbar.set)

        # 创建三列网格布局框架
        grid_frame = ttk.Frame(scrollable_frame)
        grid_frame.pack(fill=tk.BOTH, expand=True, padx=5, pady=5)

        # 配置三列,每列权重相等
        for col in range(3):
            grid_frame.columnconfigure(col, weight=1, uniform="equal")

        # 获取数据
        data_list = self.market_nav_config.get(config_key, [])
        # 不要自动从默认配置加载,保持用户配置(即使是空的)
        # 如果用户需要恢复,可以使用"恢复默认"按钮

        if not data_list:
            ttk.Label(grid_frame, text="暂无配置,可点击右上方【编辑导航】添加。", foreground="gray").grid(
                row=0, column=0, columnspan=3, sticky="w"
            )
            canvas.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
            scrollbar.pack(side=tk.RIGHT, fill=tk.Y)
            return

        # 确保每个项目都有排序字段
        for item in data_list:
            if "sort_order" not in item:
                item["sort_order"] = len(data_list)

        # 按排序字段排序
        data_list = sorted(data_list, key=lambda x: x.get("sort_order", 999))

        # 存储按钮引用,用于拖拽
        button_refs = []

        # 创建按钮(三列布局,由上到下,由左到右)
        for idx, item in enumerate(data_list):
            name = item.get("name", "")
            url = item.get("url", "")
            desc = item.get("desc", "")
            sort_order = item.get("sort_order", idx + 1)

            # 判断是否为排名/热榜类按钮
            is_rank_hot = any(keyword in name for keyword in ["榜", "排名", "热", "排行", "统计", "明细", "天梯"])

            # 优先使用配置的颜色,否则根据排序和类型设置字体大小和颜色
            bg_color = item.get("bg_color", "")
            fg_color = item.get("fg_color", "")

            if not bg_color or not fg_color:
                # 如果没有配置颜色,使用默认逻辑
                if is_rank_hot:
                    if sort_order == 1:
                        font_size = 18
                        bg_color = "red"
                        fg_color = "white"
                    elif sort_order == 2:
                        font_size = 16
                        bg_color = "orange"
                        fg_color = "white"
                    else:
                        font_size = 14
                        bg_color = "#FF6B35"
                        fg_color = "white"
                else:
                    if sort_order == 1:
                        font_size = 18
                        bg_color = "red"
                        fg_color = "white"
                    elif sort_order == 2:
                        font_size = 16
                        bg_color = "orange"
                        fg_color = "white"
                    elif sort_order == 3:
                        font_size = 14
                        bg_color = "blue"
                        fg_color = "white"
                    else:
                        font_size = 12
                        bg_color = "lightgray"
                        fg_color = "black"
            else:
                # 如果配置了颜色,根据字体大小设置(如果没有配置字体大小,使用默认值)
                if is_rank_hot or sort_order <= 3:
                    font_size = item.get("font_size", 14)
                else:
                    font_size = item.get("font_size", 12)

            def open_link(u=url, n=name, d=desc):
                import webbrowser
                if u:
                    webbrowser.open(u)
                    self.root.clipboard_clear()
                    self.root.clipboard_append(u)
                    self.root.update()
                else:
                    messagebox.showwarning("提示", f"按钮 '{n}' 的链接未配置")

            # 计算网格位置(三列布局)
            row = idx // 3
            col = idx % 3

            # 创建复选框和按钮的容器框架
            btn_frame = ttk.Frame(grid_frame)
            btn_frame.grid(row=row, column=col, padx=4, pady=3, sticky="ew")

            # 创建复选框,加载保存的状态
            checkbox_key = f"{config_key}_{idx}"
            saved_state = self.market_nav_checkbox_states.get(checkbox_key, False)
            checkbox_var = tk.BooleanVar(value=saved_state)
            if not hasattr(self, 'market_nav_checkboxes'):
                self.market_nav_checkboxes = {}
            self.market_nav_checkboxes[checkbox_key] = {
                'var': checkbox_var,
                'name': name,
                'url': url,
                'config_key': config_key
            }
            checkbox = ttk.Checkbutton(btn_frame, variable=checkbox_var,
                                       command=lambda k=checkbox_key, v=checkbox_var: self._save_market_nav_checkbox_state(k, v.get()))
            checkbox.pack(side=tk.LEFT, padx=(0, 3))

            # 按钮文本:如果有描述则显示名称和描述,否则只显示名称
            btn_text = f"{name}\n{desc}" if desc else name

            link_btn = tk.Button(
                btn_frame,
                text=btn_text,
                font=("TkDefaultFont", font_size, "bold" if is_rank_hot or sort_order <= 3 else "normal"),
                bg=bg_color,
                fg=fg_color,
                cursor="hand2",
                relief=tk.RAISED,
                bd=2,
                padx=10,
                pady=5,
                wraplength=180,
                command=lambda u=url, n=name, d=desc: open_link(u, n, d)
            )
            link_btn.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)

            # 存储按钮信息用于拖拽(注意:现在按钮在btn_frame中)
            button_info = {
                "button": link_btn,
                "button_frame": btn_frame,  # 添加按钮框架引用
                "item": item,
                "row": row,
                "col": col,
                "index": idx,
                "config_key": config_key
            }
            button_refs.append(button_info)

            # 实现拖拽功能(与合并标签页相同的逻辑)
            def on_drag_start(event, btn_info=button_info):
                btn_info["drag_start_x"] = event.x
                btn_info["drag_start_y"] = event.y
                btn_info["drag_start_root_x"] = event.x_root
                btn_info["drag_start_root_y"] = event.y_root
                btn_info["dragging"] = False
                btn_info["drag_threshold"] = 5
                btn_info["original_row"] = btn_info["row"]
                btn_info["original_col"] = btn_info["col"]
                btn_info["original_x"] = btn_info["button_frame"].winfo_x()
                btn_info["original_y"] = btn_info["button_frame"].winfo_y()

            def on_drag_motion(event, btn_info=button_info):
                dx = abs(event.x_root - btn_info["drag_start_root_x"])
                dy = abs(event.y_root - btn_info["drag_start_root_y"])
                distance = (dx**2 + dy**2)**0.5

                if not btn_info.get("dragging", False) and distance > btn_info["drag_threshold"]:
                    btn_info["dragging"] = True
                    btn_info["button_frame"].grid_remove()
                    btn_info["button_frame"].place(x=btn_info["original_x"], y=btn_info["original_y"])
                    btn_info["button_frame"].lift()

                if btn_info.get("dragging", False):
                    new_x = btn_info["original_x"] + (event.x - btn_info["drag_start_x"])
                    new_y = btn_info["original_y"] + (event.y - btn_info["drag_start_y"])
                    frame_x = grid_frame.winfo_x()
                    frame_y = grid_frame.winfo_y()
                    frame_width = grid_frame.winfo_width()
                    frame_height = grid_frame.winfo_height()
                    btn_width = btn_info["button_frame"].winfo_width()
                    btn_height = btn_info["button_frame"].winfo_height()

                    new_x = max(frame_x, min(new_x, frame_x + frame_width - btn_width))
                    new_y = max(frame_y, min(new_y, frame_y + frame_height - btn_height))

                    btn_info["button_frame"].place(x=new_x, y=new_y)

            def on_drag_end(event, btn_info=button_info):
                was_dragging = btn_info.get("dragging", False)
                btn_info["dragging"] = False

                if was_dragging:
                    btn_x = btn_info["button_frame"].winfo_x() - grid_frame.winfo_x()
                    btn_y = btn_info["button_frame"].winfo_y() - grid_frame.winfo_y()

                    cell_width = grid_frame.winfo_width() // 3
                    btn_height = btn_info["button_frame"].winfo_height()
                    if btn_height == 1:
                        btn_height = 50
                    cell_height = btn_height + 6

                    target_col = min(2, max(0, int(btn_x / cell_width)))
                    target_row = max(0, int(btn_y / cell_height))
                    target_idx = target_row * 3 + target_col

                    target_idx = min(len(button_refs) - 1, max(0, target_idx))

                    btn_info["button_frame"].place_forget()
                    btn_info["button_frame"].grid(row=btn_info["row"], column=btn_info["col"], padx=4, pady=3, sticky="ew")

                    if target_idx != btn_info["index"]:
                        self._reorder_single_config_buttons(button_refs, btn_info["index"], target_idx, config_key)

            link_btn.bind("<Button-1>", on_drag_start)
            link_btn.bind("<B1-Motion>", on_drag_motion)
            link_btn.bind("<ButtonRelease-1>", on_drag_end)

        canvas.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        scrollbar.pack(side=tk.RIGHT, fill=tk.Y)

        # 添加编辑按钮
        edit_frame = ttk.Frame(tab_frame)
        edit_frame.pack(fill=tk.X, padx=5, pady=5)
        # 根据config_key确定编辑导航的标签页索引
        if config_key == "indices":
            edit_tab_idx = 0
        elif config_key == "dv_accounts":
            edit_tab_idx = 3  # 需要添加大V公众号标签页
        else:
            edit_tab_idx = None

        if edit_tab_idx is not None:
            ttk.Button(edit_frame, text="编辑导航", command=lambda: self.show_market_nav_editor(default_tab=edit_tab_idx)).pack(side=tk.LEFT, padx=5)
        else:
            ttk.Button(edit_frame, text="编辑导航", command=self.show_market_nav_editor).pack(side=tk.LEFT, padx=5)
        # 添加"设定为默认"按钮
        ttk.Button(edit_frame, text="设定为默认", command=lambda: self.set_as_default_config(config_key)).pack(side=tk.LEFT, padx=5)

    def _refresh_single_config_tab(self, config_key):
        """刷新单个配置的标签页"""
        if not hasattr(self, 'market_notebook') or not self.market_notebook:
            return

        tab_text_map = {
            "indices": "宏观&指数",
            "dv_accounts": "大V公众号"
        }
        title_map = {
            "indices": "影响股市情绪与流动性的核心指标:",
            "dv_accounts": "精选财经大V公众号:点击打开公众号介绍页,可复制文章或扫码关注。"
        }

        tab_text = tab_text_map.get(config_key)
        title_text = title_map.get(config_key)

        if not tab_text or not title_text:
            return

        # 查找对应的标签页
        for i in range(self.market_notebook.index("end")):
            if self.market_notebook.tab(i, "text") == tab_text:
                tab_frame = self.market_notebook.nametowidget(self.market_notebook.tabs()[i])
                self._create_draggable_button_grid(tab_frame, config_key, title_text)
                break

    def _reorder_single_config_buttons(self, button_refs, from_idx, to_idx, config_key):
        """重新排列单个配置的按钮顺序并更新排序"""
        if from_idx == to_idx:
            return

        # 移动按钮引用
        moved_item = button_refs.pop(from_idx)
        button_refs.insert(to_idx, moved_item)

        # 更新所有按钮的排序字段和网格位置
        for idx, btn_info in enumerate(button_refs):
            btn_info["index"] = idx
            btn_info["row"] = idx // 3
            btn_info["col"] = idx % 3
            btn_info["item"]["sort_order"] = idx + 1

            # 更新按钮的网格位置
            btn_info["button"].grid(row=btn_info["row"], column=btn_info["col"], padx=4, pady=3, sticky="ew")

        # 更新配置(确保移除_type标记,但保留其他所有字段)
        data_list = []
        for btn_info in button_refs:
            item = btn_info["item"].copy()
            # 移除临时标记
            cleaned_item = {k: v for k, v in item.items() if k != "_type"}
            data_list.append(cleaned_item)

        self.market_nav_config[config_key] = data_list

        # 保存配置
        self.save_market_nav_config()

    def _reorder_buttons(self, button_refs, from_idx, to_idx):
        """重新排列按钮顺序并更新排序"""
        if from_idx == to_idx:
            return

        # 移动按钮引用
        moved_item = button_refs.pop(from_idx)
        button_refs.insert(to_idx, moved_item)

        # 更新所有按钮的排序字段和网格位置
        for idx, btn_info in enumerate(button_refs):
            btn_info["index"] = idx
            btn_info["row"] = idx // 3
            btn_info["col"] = idx % 3
            btn_info["item"]["sort_order"] = idx + 1

            # 更新按钮的网格位置
            btn_info["button"].grid(row=btn_info["row"], column=btn_info["col"], padx=4, pady=3, sticky="ew")

        # 保存配置
        # 分别更新indices、portals和hot_sources的排序
        indices_data = []
        portals_data = []
        hot_sources_data = []

        for btn_info in button_refs:
            item = btn_info["item"].copy()  # 复制item,避免修改原始数据
            item_type = item.get("_type", "")
            # 移除临时标记(但保留其他所有字段)
            cleaned_item = {}
            # 保留所有有效字段
            for key, value in item.items():
                if key != "_type":  # 只移除_type标记
                    cleaned_item[key] = value

            # 确保保留所有字段(名称、链接、描述、颜色、排序等)
            if item_type == "indices":
                indices_data.append(cleaned_item)
            elif item_type == "portals":
                portals_data.append(cleaned_item)
            elif item_type == "hot_sources":
                hot_sources_data.append(cleaned_item)

        # 更新配置
        self.market_nav_config["indices"] = indices_data
        self.market_nav_config["portals"] = portals_data
        self.market_nav_config["hot_sources"] = hot_sources_data

        # 保存配置
        self.save_market_nav_config()

    def _edit_hot_navigation_sort(self):
        """编辑热点导航排序"""
        # 合并portals和hot_sources
        portals = self.market_nav_config.get("portals", [])
        hot_sources = self.market_nav_config.get("hot_sources", [])

        # 如果数据为空,尝试从默认配置加载
        if not portals:
            default_portals = DEFAULT_MARKET_NAV_CONFIG.get("portals", [])
            if default_portals:
                portals = default_portals
                self.market_nav_config["portals"] = portals
        if not hot_sources:
            default_hot_sources = DEFAULT_MARKET_NAV_CONFIG.get("hot_sources", [])
            if default_hot_sources:
                hot_sources = default_hot_sources
                self.market_nav_config["hot_sources"] = hot_sources

        if portals or hot_sources:
            self.save_market_nav_config()

        all_data = portals + hot_sources

        # 创建临时配置用于编辑
        temp_config = {"all_nav": all_data}

        win = tk.Toplevel(self.root)
        win.title("热点导航排序")
        win.geometry("600x500")

        # 创建列表和排序控件
        list_frame = ttk.Frame(win)
        list_frame.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)

        # 列表显示
        listbox = tk.Listbox(list_frame, height=15)
        listbox.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)

        # 排序按钮
        sort_btn_frame = ttk.Frame(list_frame)
        sort_btn_frame.pack(side=tk.RIGHT, fill=tk.Y, padx=(5, 0))

        ttk.Button(sort_btn_frame, text="↑", command=lambda: self._move_item_up(listbox, all_data)).pack(pady=2)
        ttk.Button(sort_btn_frame, text="↓", command=lambda: self._move_item_down(listbox, all_data)).pack(pady=2)

        # 刷新列表
        def refresh_list():
            listbox.delete(0, tk.END)
            if not all_data:
                listbox.insert(tk.END, "暂无数据,请在编辑导航中添加")
            else:
                # 按排序字段排序
                sorted_list = sorted(all_data, key=lambda x: x.get("sort_order", 999))
                for idx, item in enumerate(sorted_list):
                    sort_order = item.get("sort_order", idx + 1)
                    name = item.get("name", "")
                    listbox.insert(tk.END, f"{sort_order}. {name}")

        refresh_list()

        # 保存按钮
        def save_sort():
            # 更新排序字段
            for idx, item in enumerate(all_data):
                item["sort_order"] = idx + 1

            # 分别保存到portals和hot_sources
            portal_count = len(portals)
            for idx, item in enumerate(all_data):
                if idx < portal_count:
                    if idx < len(portals):
                        portals[idx]["sort_order"] = item.get("sort_order", idx + 1)
                else:
                    hot_idx = idx - portal_count
                    if hot_idx < len(hot_sources):
                        hot_sources[hot_idx]["sort_order"] = item.get("sort_order", idx + 1)

            self.market_nav_config["portals"] = portals
            self.market_nav_config["hot_sources"] = hot_sources
            self.save_market_nav_config()
            self._create_merged_market_hot_tab()  # 刷新合并标签页
            win.destroy()

        ttk.Button(win, text="保存", command=save_sort).pack(pady=10)

    def _edit_nav_sort(self, key, title):
        """编辑导航排序的通用函数"""
        data_list = self.market_nav_config.get(key, [])

        # 如果数据为空,尝试从默认配置加载
        if not data_list:
            default_data = DEFAULT_MARKET_NAV_CONFIG.get(key, [])
            if default_data:
                data_list = default_data
                self.market_nav_config[key] = data_list
                self.save_market_nav_config()

        win = tk.Toplevel(self.root)
        win.title(title)
        win.geometry("600x500")

        # 创建列表和排序控件
        list_frame = ttk.Frame(win)
        list_frame.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)

        # 列表显示
        listbox = tk.Listbox(list_frame, height=15)
        listbox.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)

        # 排序按钮
        sort_btn_frame = ttk.Frame(list_frame)
        sort_btn_frame.pack(side=tk.RIGHT, fill=tk.Y, padx=(5, 0))

        ttk.Button(sort_btn_frame, text="↑", command=lambda: self._move_item_up(listbox, data_list)).pack(pady=2)
        ttk.Button(sort_btn_frame, text="↓", command=lambda: self._move_item_down(listbox, data_list)).pack(pady=2)

        # 刷新列表
        def refresh_list():
            listbox.delete(0, tk.END)
            if not data_list:
                listbox.insert(tk.END, "暂无数据,请在编辑导航中添加")
            else:
                # 按排序字段排序
                sorted_list = sorted(data_list, key=lambda x: x.get("sort_order", 999))
                for idx, item in enumerate(sorted_list):
                    sort_order = item.get("sort_order", idx + 1)
                    name = item.get("name", "")
                    listbox.insert(tk.END, f"{sort_order}. {name}")

        refresh_list()

        # 保存按钮
        def save_sort():
            # 更新排序字段
            for idx, item in enumerate(data_list):
                item["sort_order"] = idx + 1
            self.market_nav_config[key] = data_list
            self.save_market_nav_config()
            # 刷新合并标签页(如果key是indices,需要刷新合并标签页)
            if key == "indices":
                self._create_merged_market_hot_tab()
            win.destroy()

        ttk.Button(win, text="保存", command=save_sort).pack(pady=10)

    def _move_item_up(self, listbox, data_list):
        """向上移动列表项"""
        selection = listbox.curselection()
        if not selection or selection[0] == 0:
            return
        idx = selection[0]
        # 交换数据
        data_list[idx], data_list[idx - 1] = data_list[idx - 1], data_list[idx]
        # 刷新显示
        listbox.delete(0, tk.END)
        for i, item in enumerate(data_list):
            sort_order = item.get("sort_order", i + 1)
            name = item.get("name", "")
            listbox.insert(tk.END, f"{sort_order}. {name}")
        listbox.selection_set(idx - 1)

    def _move_item_down(self, listbox, data_list):
        """向下移动列表项"""
        selection = listbox.curselection()
        if not selection or selection[0] == len(data_list) - 1:
            return
        idx = selection[0]
        # 交换数据
        data_list[idx], data_list[idx + 1] = data_list[idx + 1], data_list[idx]
        # 刷新显示
        listbox.delete(0, tk.END)
        for i, item in enumerate(data_list):
            sort_order = item.get("sort_order", i + 1)
            name = item.get("name", "")
            listbox.insert(tk.END, f"{sort_order}. {name}")
        listbox.selection_set(idx + 1)

    def update_sentiment_indicator(self, sentiment):
        """更新右下角情绪指标(文本颜色 + 红黄绿灯)"""
        try:
            if not hasattr(self, 'sentiment_canvas') or not hasattr(self, 'sentiment_value_label'):
                return
            if not self.sentiment_canvas.winfo_exists() or not self.sentiment_value_label.winfo_exists():
                return

            # 文本映射与颜色
            sentiment_text = str(sentiment or "中性")
            sentiment_map = {
                "积极": ("积极", "red"),
                "偏积极": ("偏积极", "red"),
                "消极": ("消极", "green"),
                "偏消极": ("偏消极", "green"),
                "中性": ("中性", "orange"),
            }
            display_text, color = sentiment_map.get(sentiment_text, ("中性", "orange"))
            self.sentiment_value_label.configure(text=display_text, foreground=color)

            # 画红黄绿灯
            self.sentiment_canvas.delete("all")
            # 背板
            self.sentiment_canvas.create_rectangle(5, 5, 55, 79, outline="#b0b0b0", width=1)

            # 判断哪个灯亮
            active = "yellow"
            if color == "red":
                active = "red"
            elif color == "green":
                active = "green"
            else:
                active = "yellow"

            # 颜色定义
            on_colors = {"red": "#ff4040", "yellow": "#ffbf00", "green": "#4cd964"}
            off_color = "#d0d0d0"

            # 逐个绘制
            for name, (cx, cy, r) in self._sentiment_lights.items():
                fill = on_colors[name] if name == active else off_color
                self.sentiment_canvas.create_oval(cx - r, cy - r, cx + r, cy + r, fill=fill, outline="#888888")
        except Exception as _:
            # 静默失败,避免影响主流程
            pass

