                        stop_words = ['的', '了', '是', '在', '有', '和', '就', '不', '人', '都',
                                     '一', '一个', '上', '也', '很', '到', '说', '要', '去', '你',
                                     '会', '着', '没有', '看', '好', '自己', '这']
                        word_freq = Counter([w for w in words if len(w) > 1 and w not in stop_words])
                        top_words = dict(word_freq.most_common(10))

                        # 股票提及频率统计
                        stock_mentions = {}
