    def search_text(self):
        """查找文本"""
        search_term = self.search_entry.get().strip()
        if not search_term:
            messagebox.showwarning("警告", "请输入要查找的文本")
            return

        text_widget = self.get_active_text_widget()
        if not text_widget:
            return

        # 查找所有匹配位置
        self.search_positions = []
        start = "1.0"
        while True:
            pos = text_widget.search(search_term, start, tk.END)
            if not pos:
                break
            self.search_positions.append(pos)
            start = pos + "+1c"

        if not self.search_positions:
            messagebox.showinfo("查找结果", f"未找到 '{search_term}'")
            return

        # 高亮第一个匹配项
        self.current_search_index = 0
        self.highlight_search_result()
        messagebox.showinfo("查找结果", f"找到 {len(self.search_positions)} 个匹配项")

    def search_next(self):
        """查找下一个"""
        if not self.search_positions:
            messagebox.showwarning("警告", "请先执行查找")
            return

        self.current_search_index = (self.current_search_index + 1) % len(self.search_positions)
        self.highlight_search_result()

    def search_prev(self):
        """查找上一个"""
        if not self.search_positions:
            messagebox.showwarning("警告", "请先执行查找")
            return

        self.current_search_index = (self.current_search_index - 1) % len(self.search_positions)
        self.highlight_search_result()

    def highlight_search_result(self):
        """高亮显示查找结果"""
        if not self.search_positions or self.current_search_index < 0:
            return

        text_widget = self.get_active_text_widget()
        if not text_widget:
            return

        # 清除之前的高亮
        text_widget.tag_remove("search_highlight", "1.0", tk.END)

        # 高亮当前匹配项
        pos = self.search_positions[self.current_search_index]
        search_term = self.search_entry.get().strip()
        end_pos = f"{pos}+{len(search_term)}c"

        # 添加高亮标签
        text_widget.tag_add("search_highlight", pos, end_pos)
        text_widget.tag_config("search_highlight", background="yellow")

        # 滚动到匹配位置
        text_widget.see(pos)

        # 更新位置信息
        total = len(self.search_positions)
        current = self.current_search_index + 1
        self.search_pos_label.configure(text=f"{current}/{total}")

    def export_analysis_and_wordcloud(self):
        """导出股票分析结果和词云为长图格式"""
        try:
            # 检查是否有分析结果和词云
            if not hasattr(self, 'last_analysis_result') or not self.last_analysis_result:
                messagebox.showwarning("警告", "请先进行股票分析")
                return

            # 选择导出目录
            export_dir = filedialog.askdirectory(
                title="选择导出目录",
                initialdir=self.export_dir if hasattr(self, 'export_dir') and self.export_dir else D_EXPORT_DIR
            )

            if not export_dir:
                return

            # 更新导出目录
            self.export_dir = export_dir

            # 在后台线程中执行导出
            def run_export():
                try:
                    # 生成时间戳
                    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
                    filename = f"股票分析结果_{timestamp}.png"
                    filepath = os.path.join(export_dir, filename)

                    # 创建长图
                    self.create_long_image(filepath)

                    # 显示成功消息
                    if hasattr(self, 'root') and self.root.winfo_exists():
                        self.root.after(0, lambda: messagebox.showinfo(
                            "导出成功",
                            f"已成功导出到:\n{filepath}"
                        ))

                except Exception:
                    if hasattr(self, 'root') and self.root.winfo_exists():
                        self.root.after(0, lambda: messagebox.showerror(
                            "导出失败",
                            f"导出失败:{e!s}"
                        ))

            export_thread = threading.Thread(target=run_export, daemon=True)
            export_thread.start()

        except Exception as e:
            messagebox.showerror("错误", f"导出失败:{e!s}")

    def export_to_excel_ui(self):
        """导出分析结果和词云数据到Excel"""
        try:
            # 检查是否有分析结果
            if not hasattr(self, 'last_analysis_result') or not self.last_analysis_result:
                messagebox.showwarning("警告", "请先进行股票分析,然后再导出结果")
                return

            # 选择保存路径,不设置初始文件名,让用户自由命名
            filepath = filedialog.asksaveasfilename(
                defaultextension=".xlsx",
                filetypes=[
                    ("Excel files", "*.xlsx"),
                    ("CSV files", "*.csv"),
                    ("All files", "*.*")
                ],
                initialdir=D_EXPORT_DIR,
                title="保存分析结果文件"
            )

            if filepath:
                # 显示导出进度
                progress_window = tk.Toplevel(self.root)
                progress_window.title("导出中...")
                progress_window.geometry("300x100")
                progress_window.resizable(False, False)

                # 居中显示
                progress_window.transient(self.root)
                progress_window.grab_set()

                # 进度标签
                progress_label = ttk.Label(progress_window, text="正在导出分析结果...", font=("Arial", 10))
                progress_label.pack(pady=20)

                # 进度条
                progress_bar = ttk.Progressbar(progress_window, mode='indeterminate')
                progress_bar.pack(pady=10, padx=20, fill=tk.X)
                progress_bar.start()

                def run_excel_export():
                    try:
                        print(f"开始导出到: {filepath}")
                        success = self.export_to_excel(filepath)

                        # 关闭进度窗口
                        if hasattr(self, 'root') and self.root.winfo_exists():
                            self.root.after(0, progress_window.destroy)

                        if success:
                            # 检查是否实际生成了文件
                            if os.path.exists(filepath):
                                self.root.after(0, lambda: messagebox.showinfo(
                                    "导出成功",
                                    f"分析结果已成功导出到:\n{filepath}\n\n文件大小: {os.path.getsize(filepath)} 字节"
                                ))
                            else:
                                # 检查是否有CSV文件
                                csv_filepath = filepath.replace('.xlsx', '.csv')
                                if os.path.exists(csv_filepath):
                                    self.root.after(0, lambda: messagebox.showinfo(
                                        "导出成功",
                                        f"分析结果已导出为CSV文件:\n{csv_filepath}\n\n文件大小: {os.path.getsize(csv_filepath)} 字节"
                                    ))
                                else:
                                    self.root.after(0, lambda: messagebox.showerror("导出失败", "文件未生成,请检查错误信息"))
                        else:
                            self.root.after(0, lambda: messagebox.showerror("导出失败", "导出过程中发生错误,请查看控制台输出"))

                    except Exception as e:
                        print(f"导出线程异常: {e}")
                        import traceback
                        traceback.print_exc()

                        if hasattr(self, 'root') and self.root.winfo_exists():
                            self.root.after(0, progress_window.destroy)
                            self.root.after(0, lambda: messagebox.showerror("导出错误", f"导出失败:{e!s}"))

                # 在后台线程中执行导出
                export_thread = threading.Thread(target=run_excel_export, daemon=True)
                export_thread.start()

        except Exception as e:
            print(f"导出UI异常: {e}")
            import traceback
            traceback.print_exc()
            messagebox.showerror("错误", f"导出失败:{e!s}")

    def export_to_excel(self, filepath):
        """导出分析结果到Excel文件,保留文字格式"""
        try:
            print(f"开始导出Excel文件到: {filepath}")

            # 获取股票分析结果框的所有文字内容
            result_text = ""
            result_widget = self.get_active_result_widget()
            if result_widget:
                result_text = result_widget.get("1.0", tk.END).strip()

            # 如果没有结果文字,使用分析结果
            if not result_text and hasattr(self, 'last_analysis_result') and self.last_analysis_result:
                result_text = self.last_analysis_result

            if not result_text:
                print("没有分析结果可导出")
                return False

            # 将结果文字按行分割,便于在Excel中显示
            result_lines = result_text.split('\n')

            # 创建更详细的数据结构,使用多列来更好地组织内容
            export_data = []

            # 添加标题行
            export_data.append(['股票分析结果导出', '', '', ''])
            export_data.append(['导出时间', datetime.now().strftime("%Y-%m-%d %H:%M:%S"), '', ''])
            export_data.append(['导出工具', '股票分析工具', '', ''])
            export_data.append(['文件版本', 'v1.0', '', ''])
            export_data.append(['', '', '', ''])  # 空行

            # 添加分析结果内容标题
            export_data.append(['分析结果内容:', '', '', ''])
            export_data.append(['', '', '', ''])  # 空行

            # 将每一行结果添加到数据中,保持原有格式
            for line in result_lines:
                if line.strip():  # 只添加非空行
                    # 检查是否是表格行(包含多个空格分隔的数据)
                    if '  ' in line and not line.startswith('#'):
                        # 尝试按多个空格分割表格数据
                        import re
                        # 使用正则表达式按多个空格分割
                        parts = re.split(r'\s{2,}', line.strip())
                        if len(parts) > 1:
                            # 表格行,使用多列显示
                            row_data = parts[:4]  # 最多4列
                            while len(row_data) < 4:
                                row_data.append('')
                            export_data.append(row_data)
                        else:
                            # 普通行
                            export_data.append([line, '', '', ''])
                    else:
                        # 普通行,保持原有的缩进和格式
                        export_data.append([line, '', '', ''])
                else:
                    export_data.append(['', '', '', ''])  # 保留空行

            # 转换为DataFrame,使用多列来更好地显示内容
            df = pd.DataFrame(export_data, columns=['内容', '列2', '列3', '列4'])

            # 尝试不同的导出方法
            try:
                # 方法1: 使用openpyxl
                print("尝试使用openpyxl引擎导出...")
                with pd.ExcelWriter(filepath, engine='openpyxl') as writer:
                    # 创建股票分析结果工作表
                    df.to_excel(writer, sheet_name='股票分析结果', index=False)

                    # 如果有词云图片,将图片拷贝到第二个sheet
                    wordcloud_path = os.path.join(D_OUTPUT_DIR, "wordcloud.png")
                    if os.path.exists(wordcloud_path):
                        print("发现词云图片,正在添加到Excel...")
                        try:
                            from openpyxl.drawing.image import Image
                            from openpyxl.utils import get_column_letter

                            # 创建词云工作表
                            wordcloud_sheet = writer.book.create_sheet("词云图片")

                            # 添加词云图片
                            img = Image(wordcloud_path)
                            # 调整图片大小以适应Excel
                            img.width = 400
                            img.height = 300
                            wordcloud_sheet.add_image(img, 'A1')

                            # 添加图片信息
                            wordcloud_sheet['A15'] = '词云图片信息'
                            wordcloud_sheet['A16'] = f'生成时间: {datetime.now().strftime("%Y-%m-%d %H:%M:%S")}'
                            wordcloud_sheet['A17'] = f'图片文件: {wordcloud_path}'
                            wordcloud_sheet['A18'] = f'图片路径: {os.path.abspath(wordcloud_path)}'

                            print("词云图片已成功添加到Excel")
                        except Exception as img_error:
                            print(f"添加词云图片失败: {img_error}")
                            # 如果图片添加失败,创建词云信息sheet
                            wordcloud_info = {
                                '词云信息': [
                                    '词云图片已生成',
                                    f'生成时间: {datetime.now().strftime("%Y-%m-%d %H:%M:%S")}',
                                    '词云图片文件: wordcloud.png',
                                    '图片路径: ' + os.path.abspath("wordcloud.png"),
                                    f'图片添加失败: {img_error!s}'
                                ]
                            }
                            wordcloud_df = pd.DataFrame(wordcloud_info)
                            wordcloud_df.to_excel(writer, sheet_name='词云信息', index=False)
                    else:
                        print("未找到词云图片文件")

                print("Excel文件导出成功!")
                return True

            except ImportError as e:
                print(f"openpyxl不可用: {e}")
                try:
                    # 方法2: 使用xlsxwriter
                    print("尝试使用xlsxwriter引擎导出...")
                    with pd.ExcelWriter(filepath, engine='xlsxwriter') as writer:
                        df.to_excel(writer, sheet_name='股票分析结果', index=False)

                        # 如果有词云图片,添加词云信息
                        wordcloud_path = "wordcloud.png"
                        if os.path.exists(wordcloud_path):
                            print("发现词云图片,正在添加词云信息...")
                            wordcloud_info = {
                                '词云信息': [
                                    '词云图片已生成',
                                    f'生成时间: {datetime.now().strftime("%Y-%m-%d %H:%M:%S")}',
                                    '词云图片文件: wordcloud.png',
                                    '图片路径: ' + os.path.abspath("wordcloud.png"),
                                    '注意: xlsxwriter不支持直接插入图片,请查看wordcloud.png文件'
                                ]
                            }
                            wordcloud_df = pd.DataFrame(wordcloud_info)
                            wordcloud_df.to_excel(writer, sheet_name='词云信息', index=False)

                    print("Excel文件导出成功!")
                    return True

                except ImportError as e2:
                    print(f"xlsxwriter也不可用: {e2}")
                    try:
                        # 方法3: 使用默认引擎
                        print("尝试使用默认引擎导出...")
                        df.to_excel(filepath, sheet_name='股票分析结果', index=False)

                        print("Excel文件导出成功!")
                        return True

                    except Exception as e3:
                        print(f"默认引擎也失败: {e3}")
                        # 方法4: 导出为CSV作为备选
                        print("尝试导出为CSV文件...")
                        csv_filepath = filepath.replace('.xlsx', '.csv')
                        df.to_csv(csv_filepath, index=False, encoding='utf-8-sig')
                        print(f"已导出为CSV文件: {csv_filepath}")
                        return True

            except Exception as e:
                print(f"Excel导出过程中出错: {e}")
                # 最后的备选方案:导出为CSV
                try:
                    print("尝试导出为CSV文件作为备选...")
                    csv_filepath = filepath.replace('.xlsx', '.csv')
                    df.to_csv(csv_filepath, index=False, encoding='utf-8-sig')
                    print(f"已导出为CSV文件: {csv_filepath}")
                    return True
                except Exception as csv_e:
                    print(f"CSV导出也失败: {csv_e}")
                    return False

        except Exception as e:
            print(f"导出Excel失败: {e}")
            import traceback
            traceback.print_exc()
            return False

    def create_long_image(self, filepath):
        """创建长图,包含分析结果和词云"""
        try:
            # 检查词云图片是否存在
            wordcloud_path = "wordcloud.png"
            if not os.path.exists(wordcloud_path):
                raise FileNotFoundError("词云图片不存在,请先生成词云")

            # 创建画布

            # 加载词云图片
            wordcloud_img = Image.open(wordcloud_path)
            wordcloud_width, wordcloud_height = wordcloud_img.size

            # 计算分析结果文本的高度
            result_text = self.last_analysis_result
            lines = result_text.split('\n')

            # 设置字体和行高
            try:
                font = ImageFont.truetype("C:/Windows/Fonts/simhei.ttf", 16)
            except:
                font = ImageFont.load_default()

            # 获取行高(兼容不同版本的PIL)
            try:
                # 新版本PIL
                line_height = font.getbbox("测试")[3] + 5
            except:
                try:
                    # 旧版本PIL
                    line_height = font.getsize("测试")[1] + 5
                except:
                    line_height = 20  # 默认行高

            text_height = len(lines) * line_height

            # 计算总高度和宽度
            total_height = text_height + wordcloud_height + 100  # 100是间距
            total_width = max(800, wordcloud_width)  # 至少800像素宽

            # 创建长图
            long_image = Image.new('RGB', (total_width, total_height), 'white')
            draw = ImageDraw.Draw(long_image)

            # 绘制标题
            title = "股票分析结果报告"
            try:
                title_font = ImageFont.truetype("C:/Windows/Fonts/simhei.ttf", 24)
            except:
                title_font = ImageFont.load_default()

            title_bbox = draw.textbbox((0, 0), title, font=title_font)
            title_width = title_bbox[2] - title_bbox[0]
            title_x = (total_width - title_width) // 2
            draw.text((title_x, 20), title, fill='black', font=title_font)

            # 绘制分析结果文本
            y_offset = 80
            for line in lines:
                if line.strip():
                    draw.text((20, y_offset), line, fill='black', font=font)
                y_offset += line_height

            # 绘制分隔线
            separator_y = y_offset + 20
            draw.line([(20, separator_y), (total_width - 20, separator_y)], fill='gray', width=2)

            # 绘制词云标题
            wordcloud_title = "词云分析"
            wordcloud_title_bbox = draw.textbbox((0, 0), wordcloud_title, font=title_font)
            wordcloud_title_width = wordcloud_title_bbox[2] - wordcloud_title_bbox[0]
            wordcloud_title_x = (total_width - wordcloud_title_width) // 2
            draw.text((wordcloud_title_x, separator_y + 20), wordcloud_title, fill='black', font=title_font)

            # 粘贴词云图片
            wordcloud_x = (total_width - wordcloud_width) // 2
            wordcloud_y = separator_y + 60
            long_image.paste(wordcloud_img, (wordcloud_x, wordcloud_y))

            # 绘制时间戳
            timestamp = datetime.now().strftime("生成时间:%Y-%m-%d %H:%M:%S")
            timestamp_bbox = draw.textbbox((0, 0), timestamp, font=font)
            timestamp_width = timestamp_bbox[2] - timestamp_bbox[0]
            timestamp_x = total_width - timestamp_width - 20
            timestamp_y = total_height - 30
            draw.text((timestamp_x, timestamp_y), timestamp, fill='gray', font=font)

            # 保存长图
            long_image.save(filepath, 'PNG', quality=95)

        except Exception as e:
            raise Exception(f"创建长图失败:{e!s}")

    def update_analysis_result(self, result):
        """更新分析结果并保存用于导出"""
        self.last_analysis_result = result
        result_widget = self.get_active_result_widget()
        if result_widget:
            result_widget.delete("1.0", tk.END)
            self.insert_colored_result(result)

    def analyze_and_generate(self):
        """同时分析文本并生成词云(处理所有标签页)"""
        # 仅使用当前活动左侧标签页文本
        combined_text = self.get_current_text()
        if not combined_text or not combined_text.strip():
            messagebox.showwarning("警告", "请输入文本内容")
            return

        # 获取标签页名称和时间
        tab_name = self.get_active_text_title()
        time_str = datetime.now().strftime("%Y-%m-%d %H:%M:%S")

        # 在后台线程中运行分析和词云生成
        def run_analysis_and_wordcloud():
            try:
                # 同时进行文本分析和词云生成
                result = analyze_stock_keywords_local(combined_text)
                # 情绪指标更新(基于多维度文本分析)
                try:
                    dimension_analysis = analyze_text_dimensions(combined_text)
                    if dimension_analysis and hasattr(self, 'root') and self.root.winfo_exists():
                        sentiment_val = dimension_analysis.get('sentiment', '中性')
                        self.root.after(0, lambda: self.update_sentiment_indicator(sentiment_val))
                except Exception:
                    pass
                generate_wordcloud(combined_text, self.wordcloud_callback, tab_name=tab_name, time_str=time_str)

                # 更新分析结果
                if hasattr(self, 'root') and self.root.winfo_exists():
                    self.root.after(0, lambda: self.update_analysis_result(result))
                    self.root.after(0, lambda: messagebox.showinfo("成功", "分析完成,词云生成中..."))
            except Exception:
                if hasattr(self, 'root') and self.root.winfo_exists():
                    self.root.after(0, lambda: messagebox.showerror("错误", f"分析失败: {e}"))

        analysis_thread = threading.Thread(target=run_analysis_and_wordcloud, daemon=True)
        analysis_thread.start()

    def update_result_text(self, result):
        """更新结果文本框(线程安全)"""
        try:
            result_widget = self.get_active_result_widget()
            if result_widget:
                result_widget.delete("1.0", tk.END)
                if result:
                    result_widget.insert("1.0", result)
                    print(f"✅ 分析结果已更新,长度: {len(result)} 字符")
                else:
                    result_widget.insert("1.0", "❌ 分析结果为空")
                    print("⚠️ 分析结果为空")
        except Exception as e:
            print(f"更新结果文本框失败: {e}")

    def analyze_text(self):
        """分析文本"""
        text = self.get_current_text()
        if not text:
            messagebox.showwarning("警告", "请输入文本内容")
            return

        # 在后台线程中运行分析
        def run_analysis():
            try:
                result = analyze_stock_keywords_local(text)
                if hasattr(self, 'root') and self.root.winfo_exists():
                    self.root.after(0, lambda: self.update_result_text(result))
                    self.root.after(0, lambda: messagebox.showinfo("成功", "分析完成"))
            except Exception:
                if hasattr(self, 'root') and self.root.winfo_exists():
                    self.root.after(0, lambda: messagebox.showerror("错误", f"分析失败: {e}"))

        analysis_thread = threading.Thread(target=run_analysis, daemon=True)
        analysis_thread.start()

    def generate_wordcloud_ui(self):
        """生成词云UI"""
        text = self.get_current_text()
        if not text:
            messagebox.showwarning("警告", "请输入文本内容")
            return

        # 获取标签页名称和时间
        tab_name = self.get_active_text_title()
        time_str = datetime.now().strftime("%Y-%m-%d %H:%M:%S")

        # 在后台线程中生成词云
        def run_wordcloud():
            try:
                # 提取股票信息用于词云(保存股票数据)
                stock_names, _ = extract_stock_names(text)
                wordcloud_stocks = []
                current_date = datetime.now().strftime('%Y-%m-%d')

                for stock_name in stock_names:
                    # 提取股票逻辑
                    logic = get_stock_logic(text, stock_name)
                    if not logic or logic == "未找到明确逻辑":
                        # 尝试从上下文中提取
                        context = extract_stock_context(text, [stock_name])
                        contexts = context.get(stock_name, [])
                        if contexts and contexts[0] != "未找到相关内容":
                            logic = contexts[0][:200]  # 限制长度
                        else:
                            logic = "无详细逻辑"

                    wordcloud_stocks.append({
                        'name': stock_name,
                        'logic': logic,
                        'date': current_date,
                        'source': '词云分析'
                    })

                # 保存词云股票数据
                self.wordcloud_stocks_data = wordcloud_stocks

                generate_wordcloud(text, self.wordcloud_callback, tab_name=tab_name, time_str=time_str)
            except Exception:
                if hasattr(self, 'root') and self.root.winfo_exists():
                    self.root.after(0, lambda: messagebox.showerror("错误", f"生成词云失败: {e}"))

        wordcloud_thread = threading.Thread(target=run_wordcloud, daemon=True)
        wordcloud_thread.start()

    def wordcloud_callback(self, message):
        """词云生成回调"""
        if message.startswith("词云生成完成"):
            try:
                # 新建结果标签页名称:左边标签页前五个字 + "词云"
                try:
                    src_title = self.get_active_text_title()
                    prefix = (src_title or "未命名")[:5]
                    wc_tab_title = f"{prefix}词云"
                    wc_tab_id = self.create_result_tab(wc_tab_title)
                    wc_widget = self.result_tabs[wc_tab_id]['widget']
                    if wc_widget:
                        wc_widget.insert("1.0", f"词云生成完成({datetime.now().strftime('%H:%M:%S')})\n")
                except Exception:
                    pass

                # 加载词云图片
                image = Image.open("wordcloud.png")
                # 调整图片大小以适应显示区域(缩小到60%)
                image = image.resize((300, 240), Image.Resampling.LANCZOS)  # 500*0.6=300, 400*0.6=240
                photo = ImageTk.PhotoImage(image)

                # 更新词云显示
                if hasattr(self, 'wordcloud_label') and self.wordcloud_label.winfo_exists():
                    self.wordcloud_label.configure(image=photo, text="")
                    self.wordcloud_label.image = photo
                    # 绑定点击事件,弹出大图
                    self.wordcloud_label.bind("<Button-1>", self.show_wordcloud_large)

                # 将词云图片添加到词云标签页(按照时间顺序,最新的在下面)
                try:
                    if hasattr(self, 'wordcloud_tab_widget') and self.wordcloud_tab_widget.winfo_exists():
                        # 获取当前时间
                        current_time = datetime.now().strftime("%Y-%m-%d %H:%M:%S")

                        # 在词云标签页末尾插入时间戳和图片
                        # 先插入分隔线和时间
                        self.wordcloud_tab_widget.insert(tk.END, f"\n{'='*50}\n")
                        self.wordcloud_tab_widget.insert(tk.END, f"生成时间: {current_time}\n")

                        # 插入词云图片(使用更大的尺寸以便查看)
                        display_image = Image.open("wordcloud.png")
                        # 调整到合适大小(宽度600,保持比例)
                        original_width, original_height = display_image.size
                        aspect_ratio = original_height / original_width
                        new_width = 600
                        new_height = int(new_width * aspect_ratio)
                        display_image = display_image.resize((new_width, new_height), Image.Resampling.LANCZOS)
                        display_photo = ImageTk.PhotoImage(display_image)

                        # 在文本框中插入图片
                        self.wordcloud_tab_widget.image_create(tk.END, image=display_photo)
                        self.wordcloud_tab_widget.insert(tk.END, "\n")

                        # 保存图片引用,防止被垃圾回收
                        if not hasattr(self, 'wordcloud_images'):
                            self.wordcloud_images = []
                        self.wordcloud_images.append(display_photo)

                        # 滚动到底部显示最新词云
                        self.wordcloud_tab_widget.see(tk.END)

                        # 切换到词云标签页
                        if hasattr(self, 'wordcloud_tab_id'):
                            tab_info = self.text_widgets.get(self.wordcloud_tab_id)
                            if tab_info:
                                self.text_notebook.select(tab_info['frame'])
                except Exception as e:
                    print(f"添加词云到标签页失败: {e}")
                    import traceback
                    traceback.print_exc()

                # 同时显示股票分析结果
                text = self.get_current_text()
                if text:
                    try:
                        result = analyze_stock_keywords_local(text)
                        if hasattr(self, 'root') and self.root.winfo_exists():
                            self.root.after(0, lambda: self.update_result_text(result))
                    except Exception as e:
                        print(f"显示分析结果失败: {e}")

                if hasattr(self, 'root') and self.root.winfo_exists():
                    self.root.after(0, lambda: messagebox.showinfo("成功", "词云生成完成"))
            except Exception as e:
                if hasattr(self, 'root') and self.root.winfo_exists():
                    error_msg = str(e)
                    self.root.after(0, lambda: messagebox.showerror("错误", f"显示词云失败: {error_msg}"))
        else:
            if hasattr(self, 'root') and self.root.winfo_exists():
                self.root.after(0, lambda: messagebox.showwarning("警告", message))

    def show_wordcloud_large(self, event=None):
        """点击词云时弹出2倍大小的词云图片,不超过屏幕三分之二,保持原始宽高比"""
        try:
            wordcloud_path = "wordcloud.png"
            if not os.path.exists(wordcloud_path):
                messagebox.showwarning("警告", "词云图片不存在,请先生成词云")
                return

            # 获取屏幕尺寸
            screen_width = self.root.winfo_screenwidth()
            screen_height = self.root.winfo_screenheight()
            max_width = int(screen_width * 2 / 3)
            max_height = int(screen_height * 2 / 3)

            # 加载词云图片
            image = Image.open(wordcloud_path)
            original_width = image.width
            original_height = image.height
            original_ratio = original_width / original_height  # 保持原始宽高比

            # 放大2倍
            new_width = original_width * 2
            new_height = original_height * 2

            # 如果超过屏幕三分之二,则按比例缩小(保持宽高比)
            if new_width > max_width or new_height > max_height:
                width_ratio = max_width / new_width
                height_ratio = max_height / new_height
                ratio = min(width_ratio, height_ratio)  # 使用较小的比例以确保两个方向都不超过
                new_width = int(new_width * ratio)
                new_height = int(new_height * ratio)

            # 确保宽高比与原始图片一致(防止因整数舍入导致的偏差)
            # 重新计算以保持精确的宽高比
            if new_width / new_height != original_ratio:
                # 以宽度为准,调整高度
                new_height = int(new_width / original_ratio)
                # 如果调整后的高度超过限制,则以高度为准
                if new_height > max_height:
                    new_height = max_height
                    new_width = int(new_height * original_ratio)

            # 调整图片大小,保持宽高比
            large_image = image.resize((new_width, new_height), Image.Resampling.LANCZOS)
            photo = ImageTk.PhotoImage(large_image)

            # 创建新窗口,窗口大小要包含按钮的高度
            button_height = 50  # 为关闭按钮预留空间
            window_width = new_width
            window_height = new_height + button_height

            large_window = tk.Toplevel(self.root)
            large_window.title("词云大图")
            large_window.geometry(f"{window_width}x{window_height}")

            # 创建画布用于显示图片(使用画布可以更好地控制显示)
            canvas = tk.Canvas(large_window, width=new_width, height=new_height, highlightthickness=0)
            canvas.pack(pady=10)
            canvas.create_image(new_width // 2, new_height // 2, image=photo, anchor=tk.CENTER)
            canvas.image = photo  # 保持引用,防止被垃圾回收

            # 添加关闭按钮
            close_button = ttk.Button(large_window, text="关闭", command=large_window.destroy)
            close_button.pack(pady=10)

        except Exception as e:
            messagebox.showerror("错误", f"显示词云大图失败: {e}")

    def start_realtime_update(self):
        """启动实时数据更新"""
        def update_loop():
            while True:
                try:
                    if hasattr(self, 'root') and self.root.winfo_exists():
                        self.update_realtime_data()
                    time.sleep(1)  # 每秒更新一次
                except Exception as e:
                    print(f"实时更新错误: {e}")
                    time.sleep(5)  # 出错时等待5秒

        update_thread = threading.Thread(target=update_loop, daemon=True)
        update_thread.start()

    def update_realtime_data(self):
        """更新实时数据"""
        try:
            # 获取当前文本中的股票
            text = self.get_current_text()
            if not text:
                return

            stock_names, _ = extract_stock_names(text)
            if not stock_names:
                return

            # 更新实时数据
            realtime_info = "🕐 实时数据更新中...\n\n"

            for stock_name in stock_names[:10]:  # 最多显示10只股票
                # 获取股票实时数据
                stock_data = None  # 实时数据获取功能已移除
                if stock_data:
                    # 获取板块信息
                    sector = get_stock_sector(stock_name)

                    # 获取板块内其他股票(最多3只)
                    sector_stocks = []  # 板块股票获取功能已移除
                    related_stocks = [s for s in sector_stocks if s != stock_name][:3]

                    # 显示主股票信息
                    change_emoji = "📈" if stock_data['change_pct'] > 0 else "📉" if stock_data['change_pct'] < 0 else "➡️"
                    realtime_info += f"【{stock_name}】{change_emoji}\n"
                    realtime_info += f"   💰 价格: {stock_data['price']:.2f}\n"
                    realtime_info += f"   📊 涨跌幅: {stock_data['change_pct']:.2f}%\n"
                    realtime_info += f"   🏢 板块: {sector}\n"

                    # 显示关联板块股票
                    if related_stocks:
                        realtime_info += "   🔗 关联股票:\n"
                        for related_stock in related_stocks:
                            related_data = None  # 实时数据获取功能已移除
                            if related_data:
                                rel_change_emoji = "📈" if related_data['change_pct'] > 0 else "📉" if related_data['change_pct'] < 0 else "➡️"
                                realtime_info += f"      {related_stock}: {rel_change_emoji} {related_data['change_pct']:.2f}%\n"

                    realtime_info += "\n" + "─" * 40 + "\n\n"

            # 更新时间戳
            realtime_info += f"⏰ 最后更新: {datetime.now().strftime('%H:%M:%S')}\n"

            # 更新显示
            if hasattr(self, 'realtime_text') and self.realtime_text.winfo_exists():
                self.realtime_text.delete("1.0", tk.END)
                self.realtime_text.insert("1.0", realtime_info)

        except Exception as e:
            print(f"更新实时数据失败: {e}")

    def save_analyzed_stocks(self):
        """保存分析出来的股票(含逻辑和日期等字段)"""
        try:
            # 获取当前分析结果
            result_widget = self.get_active_result_widget()
            if not result_widget:
                messagebox.showwarning("警告", "请先进行分析")
                return

            result_text = result_widget.get("1.0", tk.END).strip()
            if not result_text:
                messagebox.showwarning("警告", "没有分析结果可保存")
                return

            # 从分析结果中提取股票信息(包含逻辑)
            import re
            stocks_data = []

            # 提取股票代码和名称
            stock_pattern = r'(\d{6})[::]\s*([^\n]+)'
            matches = re.findall(stock_pattern, result_text)

            # 提取每只股票的逻辑(从分析结果中查找)
            lines = result_text.split('\n')
            current_stock = None
            current_logic = []

            for i, line in enumerate(lines):
                line = line.strip()

                # 检查是否是股票行
                stock_match = re.search(r'(\d{6})[::]\s*([^\n]+)', line)
                if stock_match:
                    # 保存上一只股票的逻辑
                    if current_stock:
                        stocks_data.append({
                            'code': current_stock['code'],
                            'name': current_stock['name'],
                            'logic': '\n'.join(current_logic).strip(),
                            'date': datetime.now().strftime('%Y-%m-%d')
                        })

                    # 开始新股票
                    current_stock = {
                        'code': stock_match.group(1),
                        'name': stock_match.group(2).split()[0] if stock_match.group(2) else ''
                    }
                    current_logic = []
                elif current_stock and line:
                    # 收集逻辑信息(排除明显的标题行)
                    if not re.match(r'^[=#\-\s]+$', line) and len(line) > 5:
                        current_logic.append(line)

            # 保存最后一只股票
            if current_stock:
                stocks_data.append({
                    'code': current_stock['code'],
                    'name': current_stock['name'],
                    'logic': '\n'.join(current_logic).strip(),
                    'date': datetime.now().strftime('%Y-%m-%d')
                })

            # 如果没有从分析结果中提取到,尝试从文本中提取
            if not stocks_data and matches:
                for match in matches:
                    stock_code = match[0]
                    stock_name = match[1].split()[0] if match[1] else ""

                    # 尝试查找该股票的逻辑(在分析结果中搜索)
                    logic_lines = []
                    for line in lines:
                        if stock_code in line or stock_name in line:
                            if len(line.strip()) > 10 and not re.match(r'^[=#\-\s]+$', line.strip()):
                                logic_lines.append(line.strip())

                    stocks_data.append({
                        'code': stock_code,
                        'name': stock_name,
                        'logic': '\n'.join(logic_lines[:5]).strip() or "无详细逻辑",
                        'date': datetime.now().strftime('%Y-%m-%d')
                    })

            if not stocks_data:
                messagebox.showwarning("警告", "未找到股票信息")
                return

            # 显示保存对话框
            save_window = tk.Toplevel(self.root)
            save_window.title("保存分析股票")
            save_window.geometry("700x500")

            # 创建表格显示要保存的数据
            tree_frame = ttk.Frame(save_window)
            tree_frame.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)

            # 创建Treeview
            columns = ("股票代码", "股票名称", "逻辑", "日期")
            tree = ttk.Treeview(tree_frame, columns=columns, show="headings", height=15)

            for col in columns:
                tree.heading(col, text=col)
                if col == "逻辑":
                    tree.column(col, width=300)
                else:
                    tree.column(col, width=100)

            # 填充数据
            for stock in stocks_data:
                logic_text = stock['logic'][:100] + '...' if len(stock['logic']) > 100 else stock['logic']
                tree.insert("", tk.END, values=(
                    stock['code'],
                    stock['name'],
                    logic_text,
                    stock['date']
                ))

            # 滚动条
            scrollbar = ttk.Scrollbar(tree_frame, orient=tk.VERTICAL, command=tree.yview)
            tree.configure(yscrollcommand=scrollbar.set)
            tree.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
            scrollbar.pack(side=tk.RIGHT, fill=tk.Y)

            # 备注选择(根据当前标签页名称判断来源)
            remark_frame = ttk.Frame(save_window)
            remark_frame.pack(fill=tk.X, padx=10, pady=5)
            ttk.Label(remark_frame, text="备注:").pack(side=tk.LEFT, padx=(0, 5))
            remark_var = tk.StringVar(value="")
            remark_combo = ttk.Combobox(remark_frame, textvariable=remark_var,
                                       values=["聊天", "强势股", "韭研", "淘股吧", "文本分析", ""],
                                       width=15, state="readonly")
            remark_combo.pack(side=tk.LEFT, padx=5)

            # 根据当前标签页名称自动设置备注
            try:
                active_tab_title = self.get_active_text_title() or ""
                if "聊天" in active_tab_title or "chat" in active_tab_title.lower():
                    remark_var.set("聊天")
                elif "强势" in active_tab_title or "strong" in active_tab_title.lower():
                    remark_var.set("强势股")
                elif "韭研" in active_tab_title or "jiuyan" in active_tab_title.lower():
                    remark_var.set("韭研")
                elif "淘股吧" in active_tab_title or "taoguba" in active_tab_title.lower():
                    remark_var.set("淘股吧")
                else:
                    remark_var.set("文本分析")
            except:
                pass

            # 保存按钮
            def save_to_db():
                try:
                    saved_count = 0
                    for stock in stocks_data:
                        if save_stock_logic_to_db(
                            stock_name=stock['name'],
                            logic=stock['logic'],
                            date=stock['date'],
                            source="分析结果"
                        ):
                            saved_count += 1

                    messagebox.showinfo("成功", f"成功保存 {saved_count} 条股票数据到数据库")
                    save_window.destroy()
                except Exception as e:
                    messagebox.showerror("错误", f"保存失败: {e}")

            # 导入到自选股
            def import_to_managed_stocks():
                try:
                    remark_value = remark_var.get().strip()
                    added_count = 0
                    for stock in stocks_data:
                        if stock.get('name'):
                            # 调用自选股管理界面的添加函数
                            if hasattr(self, 'managed_stocks'):
                                # 直接添加到自选股列表
                                added_at = datetime.now().strftime("%Y-%m-%d %H:%M")
                                entry = {
                                    "name": stock['name'],
                                    "code": stock.get('code', ''),
                                    "source": "分析结果",
                                    "added_at": added_at,
                                    "remark": remark_value
                                }
                                # 检查是否已存在
                                exists = False
                                for existing in self.managed_stocks:
                                    if existing.get("name") == stock['name'] or (stock.get('code') and existing.get("code") == stock['code']):
                                        existing.update(entry)
                                        exists = True
                                        break
                                if not exists:
                                    self.managed_stocks.append(entry)
                                    if len(self.managed_stocks) > 100:
                                        self.managed_stocks = self.managed_stocks[-100:]
                                added_count += 1

                    if added_count > 0:
                        self._save_managed_stocks_to_file()
                        messagebox.showinfo("成功", f"成功导入 {added_count} 只股票到自选股管理列表(备注:{remark_value if remark_value else '无'})")
                    else:
                        messagebox.showwarning("警告", "没有可导入的股票")
                except Exception as e:
                    messagebox.showerror("错误", f"导入失败: {e}")

            button_frame = ttk.Frame(save_window)
            button_frame.pack(fill=tk.X, padx=10, pady=10)

            ttk.Button(button_frame, text="保存到数据库", command=save_to_db).pack(side=tk.LEFT, padx=5)
            ttk.Button(button_frame, text="导入到自选股", command=import_to_managed_stocks).pack(side=tk.LEFT, padx=5)
            ttk.Button(button_frame, text="取消", command=save_window.destroy).pack(side=tk.LEFT, padx=5)

        except Exception as e:
            messagebox.showerror("错误", f"保存分析股票失败: {e}")

    def create_context_menu(self):
        """创建右键菜单"""
        self.context_menu = tk.Menu(self.root, tearoff=0)
        self.context_menu.add_command(label="📋 粘贴", command=self.on_paste)
        self.context_menu.add_separator()
        self.context_menu.add_command(label="📋 粘贴网页内容", command=self.paste_webpage_with_images)
        self.context_menu.add_command(label="📋 粘贴纯文本", command=self.paste_text)
