    def crawl_taoguba_and_analyze(self):
        """爬取淘股吧并自动分析和保存股票"""
        def crawl_thread():
            try:
                # 显示进度提示
                self.root.after(0, lambda: messagebox.showinfo("提示", "开始爬取淘股吧,请稍候..."))

                # 导入淘股吧爬取模块
                try:
                    import os
                    import sys
                    current_dir = os.path.dirname(os.path.abspath(__file__))
                    # 支持打包后的环境查找脚本文件
                    script_name = "taoguba_realtime.py"
                    taoguba_path = None

                    # 1. 尝试使用 PyInstaller 打包后的路径(sys._MEIPASS)
                    if hasattr(sys, '_MEIPASS'):
                        meipass_path = os.path.join(sys._MEIPASS, script_name)
                        if os.path.exists(meipass_path):
                            taoguba_path = meipass_path

                    # 2. 尝试可执行文件所在目录的 _internal 子目录
                    if not taoguba_path:
                        if hasattr(sys, 'frozen'):
                            exe_dir = os.path.dirname(os.path.abspath(sys.executable))
                            internal_path = os.path.join(exe_dir, '_internal', script_name)
                            if os.path.exists(internal_path):
                                taoguba_path = internal_path

                    # 3. 尝试与主程序同目录
                    if not taoguba_path:
                        same_dir_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), script_name)
                        if os.path.exists(same_dir_path):
                            taoguba_path = same_dir_path

                    # 4. 尝试当前工作目录
                    if not taoguba_path:
                        cwd_path = os.path.join(os.getcwd(), script_name)
                        if os.path.exists(cwd_path):
                            taoguba_path = cwd_path

                    if not taoguba_path or not os.path.exists(taoguba_path):
                        error_msg = f"找不到淘股吧爬取程序:\n{script_name}\n\n"
                        if hasattr(sys, '_MEIPASS'):
                            error_msg += f"已尝试路径:\n1. {os.path.join(sys._MEIPASS, script_name)}\n"
                        if hasattr(sys, 'frozen'):
                            exe_dir = os.path.dirname(os.path.abspath(sys.executable))
                            error_msg += f"2. {os.path.join(exe_dir, '_internal', script_name)}\n"
                        error_msg += f"3. {os.path.join(os.path.dirname(os.path.abspath(__file__)), script_name)}\n"
                        error_msg += f"4. {os.path.join(os.getcwd(), script_name)}\n"
                        self.root.after(0, lambda: messagebox.showerror("错误", error_msg))
                        return

                    # 动态导入模块
                    import importlib.util
                    spec = importlib.util.spec_from_file_location("taoguba_realtime", taoguba_path)
                    taoguba_module = importlib.util.module_from_spec(spec)
                    spec.loader.exec_module(taoguba_module)

                    # 创建爬虫实例
                    crawler = taoguba_module.TaogubaRealtimeCrawler()

                    # 只爬取淘股吧(调用_get_articles_by_page方法)
                    articles_list = []
                    for page in range(1, 4):  # 爬取3页
                        page_articles = crawler._get_articles_by_page(page)
                        articles_list.extend(page_articles)
                        if page < 3:
                            import time
                            time.sleep(1)  # 延迟避免请求过快

                    if not articles_list:
                        self.root.after(0, lambda: messagebox.showwarning("警告", "未能获取到淘股吧文章数据"))
                        return

                    # 获取文章详细内容
                    articles_data = crawler.enrich_articles_data(articles_list)

                    # 合并所有文章内容为文本
                    combined_text = ""
                    for article in articles_data:
                        title = article.get('标题', '')
                        content = article.get('文章内容', '')
                        author = article.get('作者', '')
                        if title:
                            combined_text += f"标题:{title}\n"
                        if author:
                            combined_text += f"作者:{author}\n"
                        if content:
                            combined_text += f"内容:{content}\n"
                        combined_text += "\n" + "="*80 + "\n\n"

                    if not combined_text.strip():
                        self.root.after(0, lambda: messagebox.showwarning("警告", "未能获取到文章内容"))
                        return

                    # 在主线程中更新UI
                    def update_ui():
                        try:
                            # 切换到文本控制标签页
                            if hasattr(self, 'crawler_control_notebook'):
                                self.crawler_control_notebook.select(1)  # 切换到文本控制标签页

                            # 创建或获取文本标签页
                            if not hasattr(self, 'text_notebook') or not self.text_notebook:
                                messagebox.showerror("错误", "文本输入框未初始化")
                                return

                            # 创建新标签页或使用第一个标签页
                            tab_id = None
                            if hasattr(self, 'text_widgets') and self.text_widgets:
                                # 使用第一个标签页
                                tab_id = list(self.text_widgets.keys())[0]
                            else:
                                # 创建新标签页
                                self.tab_counter += 1
                                tab_id = f"tab_{self.tab_counter}"
                                tab_frame = ttk.Frame(self.text_notebook)
                                self.text_notebook.add(tab_frame, text=f"淘股吧_{datetime.now().strftime('%H%M%S')}")

                                text_widget = scrolledtext.ScrolledText(tab_frame, wrap=tk.WORD, font=("TkDefaultFont", 12))
                                text_widget.pack(fill=tk.BOTH, expand=True)
                                self.text_widgets[tab_id] = text_widget

                            # 将内容放入文本框
                            text_widget = self.text_widgets[tab_id]
                            text_widget.delete("1.0", tk.END)
                            text_widget.insert("1.0", combined_text)

                            # 切换到该标签页
                            self.text_notebook.select(tab_id)

                            # 自动触发分析
                            self.analyze_and_generate()

                            # 提取股票并保存到数据库
                            stock_names, _ = extract_stock_names(combined_text)
                            if stock_names:
                                current_date = datetime.now().strftime('%Y-%m-%d')
                                saved_count = 0
                                for stock_name in stock_names:
                                    try:
                                        # 保存股票到数据库(备注:淘股吧)
                                        save_stock_logic_to_db(stock_name, combined_text[:500], current_date, source="淘股吧")
                                        saved_count += 1
                                    except Exception as e:
                                        print(f"保存股票 {stock_name} 失败: {e}")

                                messagebox.showinfo("完成", f"爬取完成!\n已分析并保存 {saved_count} 只股票到数据库(备注:淘股吧)")
                            else:
                                messagebox.showinfo("完成", "爬取完成!但未识别到股票")

                        except Exception as e:
                            messagebox.showerror("错误", f"更新界面失败: {e}")
                            import traceback
                            traceback.print_exc()

                    self.root.after(0, update_ui)

                except ImportError:
                    self.root.after(0, lambda: messagebox.showerror("错误", f"导入淘股吧爬取模块失败: {e}"))
                except Exception:
                    self.root.after(0, lambda: messagebox.showerror("错误", f"爬取淘股吧失败: {e}"))
                    import traceback
                    traceback.print_exc()

            except Exception:
                self.root.after(0, lambda: messagebox.showerror("错误", f"操作失败: {e}"))
                import traceback
                traceback.print_exc()

        # 在后台线程中执行爬取
        threading.Thread(target=crawl_thread, daemon=True).start()

    def analyze_latest_n_stocks(self):
        """分析最新N条股票数据"""
        try:
            # 询问用户N的值
            n_str = simpledialog.askstring("输入数量", "请输入要分析的最新股票数据条数(N):\n留空则直接打开批量分析器", initialvalue="10")
            if not n_str or n_str.strip() == "":
                # 如果为空,直接打开批量分析器界面
                self.show_batch_stock_analyzer()
                return

            try:
                n = int(n_str)
                if n <= 0:
                    messagebox.showerror("错误", "数量必须大于0")
                    return
            except ValueError:
                messagebox.showerror("错误", "请输入有效的数字")
                return

            # 从数据库获取最新N条股票数据
            try:
                conn = sqlite3.connect(DB_PATH)
                cursor = conn.cursor()
                cursor.execute('''
                    SELECT DISTINCT stock_name
                    FROM stock_logic
                    WHERE stock_name IS NOT NULL AND stock_name != ''
                    ORDER BY created_at DESC
                    LIMIT ?
                ''', (n,))
                results = cursor.fetchall()
                conn.close()

                if not results:
                    messagebox.showwarning("警告", "数据库中没有股票数据")
                    return

                # 提取股票名称列表
                stock_names = [row[0] for row in results]

                # 打开批量分析器窗口(支持打包后的环境)
                script_name = "stock_batch_analyzer.py"
                batch_analyzer_path = None

                # 1. 尝试使用 PyInstaller 打包后的路径(sys._MEIPASS)
                if hasattr(sys, '_MEIPASS'):
                    meipass_path = os.path.join(sys._MEIPASS, script_name)
                    if os.path.exists(meipass_path):
                        batch_analyzer_path = meipass_path

                # 2. 尝试可执行文件所在目录的 _internal 子目录
                if not batch_analyzer_path:
                    if hasattr(sys, 'frozen'):
                        exe_dir = os.path.dirname(os.path.abspath(sys.executable))
                        internal_path = os.path.join(exe_dir, '_internal', script_name)
                        if os.path.exists(internal_path):
                            batch_analyzer_path = internal_path

                # 3. 尝试与主程序同目录
                if not batch_analyzer_path:
                    current_dir = os.path.dirname(os.path.abspath(__file__))
                    same_dir_path = os.path.join(current_dir, script_name)
                    if os.path.exists(same_dir_path):
                        batch_analyzer_path = same_dir_path

                # 4. 尝试当前工作目录
                if not batch_analyzer_path:
                    cwd_path = os.path.join(os.getcwd(), script_name)
                    if os.path.exists(cwd_path):
                        batch_analyzer_path = cwd_path

                if not batch_analyzer_path or not os.path.exists(batch_analyzer_path):
                    error_msg = f"找不到批量股票分析器文件:\n{script_name}\n\n"
                    if hasattr(sys, '_MEIPASS'):
                        error_msg += f"已尝试路径:\n1. {os.path.join(sys._MEIPASS, script_name)}\n"
                    if hasattr(sys, 'frozen'):
                        exe_dir = os.path.dirname(os.path.abspath(sys.executable))
                        error_msg += f"2. {os.path.join(exe_dir, '_internal', script_name)}\n"
                    error_msg += f"3. {os.path.join(os.path.dirname(os.path.abspath(__file__)), script_name)}\n"
                    error_msg += f"4. {os.path.join(os.getcwd(), script_name)}\n\n"
                    error_msg += "请确保stock_batch_analyzer.py文件已正确打包或放置在可执行文件目录中。"
                    messagebox.showerror("错误", error_msg)
                    return

                # 动态导入模块
                spec = importlib.util.spec_from_file_location("stock_batch_analyzer", batch_analyzer_path)
                batch_analyzer_module = importlib.util.module_from_spec(spec)
                spec.loader.exec_module(batch_analyzer_module)

                # 创建新窗口
                win = tk.Toplevel(self.root)
                win.title(f"批量股票分析器 - 最新{n}条数据")
                win.transient(self.root)

                # 实例化批量股票分析器
                batch_analyzer = batch_analyzer_module.StockBatchAnalyzer(win)

                # 设置5日差
                batch_analyzer.days_var.set("5")

                # 填充股票列表到输入框
                stock_text = "\n".join(stock_names)
                batch_analyzer.input_text.delete("1.0", tk.END)
                batch_analyzer.input_text.insert("1.0", stock_text)

                # 延迟自动开始分析(等待窗口完全加载)
                def auto_start_analysis():
                    try:
                        # 开始分析
                        batch_analyzer.start_analysis()

                        # 记录开始时的结果数量
                        initial_result_count = len(batch_analyzer.result_data) if hasattr(batch_analyzer, 'result_data') else 0

                        # 等待分析完成(通过检查分析线程状态和结果数据变化)
                        def check_and_save():
                            try:
                                # 检查分析线程是否还在运行
                                thread_running = (hasattr(batch_analyzer, 'analysis_thread') and
                                                batch_analyzer.analysis_thread is not None and
                                                batch_analyzer.analysis_thread.is_alive())

                                # 检查是否有新的结果数据
                                current_result_count = len(batch_analyzer.result_data) if hasattr(batch_analyzer, 'result_data') else 0
                                has_new_results = current_result_count > initial_result_count

                                if thread_running:
                                    # 如果还在分析,继续等待
                                    win.after(1000, check_and_save)
                                elif has_new_results or current_result_count > 0:
                                    # 分析完成,自动保存
                                    try:
                                        batch_analyzer.batch_insert_to_db()
                                        messagebox.showinfo("完成", f"已自动分析并保存最新{n}条股票数据到数据库\n共保存 {current_result_count} 条分析结果")
                                    except Exception as e:
                                        messagebox.showwarning("提示", f"分析完成,但自动保存失败: {e}\n请手动点击'批量插入数据库'按钮")
                                else:
                                    # 等待一段时间后再次检查(可能分析刚开始)
                                    win.after(2000, check_and_save)
                            except Exception as e:
                                # 如果检查过程中出错,提示用户手动保存
                                messagebox.showwarning("提示", f"自动检测分析状态失败: {e}\n请手动检查分析结果并保存")

                        # 延迟开始检查分析状态(给分析一些启动时间)
                        win.after(3000, check_and_save)
                    except Exception as e:
                        messagebox.showerror("错误", f"自动开始分析失败: {e}")

                # 延迟执行自动开始分析(等待窗口完全加载)
                win.after(500, auto_start_analysis)

            except Exception as e:
                messagebox.showerror("错误", f"获取股票数据失败: {e}")

        except Exception as e:
            messagebox.showerror("错误", f"操作失败: {e}")

    def show_five_star_follow_dialog(self):
        """五星跟随:统计龙头股、持仓和最近3天日期标签页的股票,按出现次数排序,并显示来源及资讯逻辑/所属板块。

        股票名称使用不同颜色加粗放大显示:
        - 同时出现在"龙头股"和"持仓"的股票:红色粗体大字
        - 仅在"龙头股"或日期标签页中的股票:橙色粗体大字
        - 仅在"持仓"或日期标签页中的股票:绿色粗体大字
        """
        import re
        from datetime import date

        # 基础标签页:持仓(1)、龙头股(2)
        tab_config = [
            (1, "持仓"),
            (2, "龙头股"),
        ]

        # 最近3天的日期标签页:group_index 7-14,对应 Notebook index = group_index + 1
        today = date.today()
        for group_index in range(7, 15):
            notebook_index = group_index + 1
            try:
                tab_text = self.position_trading_notebook.tab(notebook_index, "text")
            except Exception:
                continue
            label = str(tab_text).strip()
            # 期望格式为 MMDD,如 "0304"
            if not re.fullmatch(r"\d{4}", label):
                continue
            try:
                mm = int(label[:2])
                dd = int(label[2:])
                d = date(today.year, mm, dd)
                # 如果未来日期,按去年处理(跨年容错)
                if d > today:
                    d = date(today.year - 1, mm, dd)
            except Exception:
                continue
            delta = (today - d).days
            if 0 <= delta <= 2:
                tab_config.append((group_index, label))

        code_to_info = {}  # key -> {"code","name","count","tabs": set()}
        for group_index, tab_name in tab_config:
            holding_stocks, _, _, _ = self._get_holding_group_data(group_index)
            for slot in (holding_stocks or []):
                if not slot:
                    continue
                name, code = slot if isinstance(slot, (tuple, list)) else (slot, "")
                name = (name or "").strip()
                code = (code or "").strip()
                if not name and not code:
                    continue
                if not code and name:
                    code = get_stock_code_by_name(name) or ""
                code = str(code).zfill(6) if code else ""
                key = code if code else name
                if not key:
                    continue
                if key not in code_to_info:
                    code_to_info[key] = {"code": code or key, "name": name or key, "count": 0, "tabs": set()}
                code_to_info[key]["count"] += 1
                code_to_info[key]["tabs"].add(tab_name)
                if name:
                    code_to_info[key]["name"] = name
                if code and len(str(code)) == 6:
                    code_to_info[key]["code"] = str(code).zfill(6)

        if not code_to_info:
            messagebox.showinfo("提示", "龙头股、持仓和最近3天日期标签页中暂无股票,请先导入。", parent=self.root)
            return

        # 按出现次数从大到小排序
        sorted_items = sorted(code_to_info.items(), key=lambda x: (-x[1]["count"], x[0]))

        # 弹窗显示,后台仅获取逻辑/板块
        win = tk.Toplevel(self.root)
        win.title("五星跟随 - 统计结果")
        win.geometry("900x580")
        win.transient(self.root)
        top = ttk.Frame(win, padding=10)
        top.pack(fill=tk.BOTH, expand=True)
        ttk.Label(
            top,
            text=(
                "龙头股 + 持仓 + 最近3天日期标签页 按出现次数排序;"
                "红色=均线多头强势;蓝色=靠近10日均线多头;黄色=靠近20日均线多头。"
            ),
            font=("TkDefaultFont", 10, "bold"),
        ).pack(anchor="w")
        list_frame = ttk.Frame(top)
        list_frame.pack(fill=tk.BOTH, expand=True, pady=(8, 8))
        text_widget = tk.Text(list_frame, height=22, font=("Consolas", 9), wrap=tk.WORD)
        text_widget.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        scroll_y = ttk.Scrollbar(list_frame, orient=tk.VERTICAL, command=text_widget.yview)
        scroll_y.pack(side=tk.RIGHT, fill=tk.Y)
        text_widget.config(yscrollcommand=scroll_y.set)
        text_widget.tag_configure("header", font=("Consolas", 9, "bold"))
        text_widget.tag_configure("name_red", foreground="#c00", font=("Consolas", 11, "bold"))
        text_widget.tag_configure("name_orange", foreground="#d2691e", font=("Consolas", 11, "bold"))
        text_widget.tag_configure("name_green", foreground="#006400", font=("Consolas", 11, "bold"))
        # 均线检测后的高亮样式:强势红、靠近10日线蓝、靠近20日线黄
        text_widget.tag_configure("name_ma_strong", foreground="#ff0000", font=("Consolas", 12, "bold"))
        text_widget.tag_configure("name_ma_blue", foreground="#0000cd", font=("Consolas", 11, "bold"))
        text_widget.tag_configure("name_ma_yellow", foreground="#daa520", font=("Consolas", 11, "bold"))

        # 表头
        text_widget.insert(tk.END, "出现次数\t来源\t代码\t名称\t逻辑/所属板块\n", "header")
        # 与 sorted_items 顺序一致,每项为 {"logic_sector": str, "ma_status": str|None}
        results_cache = []
        # 尾盘选股命中列表(线程内计算,UI更新时追加到底部)
        tail_screen_hits = []

        def classify_ma_status(stock_code: str):
            """根据 1/5/10/20 日均线判断多头、靠近10/20均线等状态。

            返回:
                'strong'  : 股价站上 1/5/10/20 且四条均线上涨、多头发散
                'near10'  : 满足多头发散,且距离10日线在3%以内
                'near20'  : 满足多头发散,且距离20日线在3%以内
                None      : 条件不满足或数据不足
            """
            try:
                if not stock_code:
                    return None
                # 获取近期收盘价
                result = self._fetch_recent_daily_closes(
                    stock_code, days=40, source="default", token=self.ts_token, return_volume=False
                )
                if isinstance(result, tuple) and len(result) >= 2:
                    _, closes = result[:2]
                else:
                    closes = result or []
                if not closes or len(closes) < 22:
                    return None
                closes = [float(c) for c in closes]
                # 当前价:优先实时价,否则最后一个收盘价
                current_price = None
                try:
                    spot_row = get_realtime_spot_row(stock_code)
                    if spot_row is not None:
                        v = spot_row.get("最新价", None)
                        if v is not None:
                            current_price = float(v)
                except Exception:
                    current_price = None
                if not current_price or current_price <= 0:
                    current_price = float(closes[-1])
                # 1日线 = 最新收盘
                ma1 = float(closes[-1])
                prev_ma1 = float(closes[-2])
                # 5日均线及前一周期
                ma5 = sum(closes[-5:]) / 5
                prev_ma5 = sum(closes[-6:-1]) / 5
                # 10日均线及前一周期
                ma10 = sum(closes[-10:]) / 10
                prev_ma10 = sum(closes[-11:-1]) / 10
                # 20日均线及前一周期
                ma20 = sum(closes[-20:]) / 20
                prev_ma20 = sum(closes[-21:-1]) / 20
                # 多头发散 + 均线向上
                bull_order = (current_price > ma1 > ma5 > ma10 > ma20)
                all_up = (ma1 > prev_ma1 and ma5 > prev_ma5 and ma10 > prev_ma10 and ma20 > prev_ma20)
                if not (bull_order and all_up and ma10 > 0 and ma20 > 0):
                    return None
                dist10 = abs(current_price - ma10) / ma10 * 100
                dist20 = abs(current_price - ma20) / ma20 * 100
                if dist10 <= 3.0:
                    return "near10"
                if dist20 <= 3.0:
                    return "near20"
                return "strong"
            except Exception:
                return None

        def fetch_and_fill():
            nonlocal tail_screen_hits
            tail_screen_hits = []

            # ===== 尾盘选股(14:30-15:00)预加载:板块Top5、资金流、板块成分 =====
            sector_top5_names = []
            sector_to_codes = {}  # sector -> set(code6)
            code_to_main_inflow = {}  # code6 -> float(主力净流入净额)
            try:
                if AKSHARE_AVAILABLE:
                    import akshare as ak
                    # 1) 板块强度:涨跌幅前5(概念板块)
                    try:
                        df_sec = ak.stock_board_concept_name_em()
                        if df_sec is not None and not df_sec.empty and "涨跌幅" in df_sec.columns and "板块名称" in df_sec.columns:
                            df_sec = df_sec.sort_values("涨跌幅", ascending=False).head(5)
                            sector_top5_names = [str(x) for x in df_sec["板块名称"].tolist() if str(x).strip()]
                    except Exception:
                        sector_top5_names = []

                    # 2) 资金流向:主力资金净流入(今日)
                    try:
                        flow_rank = ak.stock_individual_fund_flow_rank(indicator="今日")
                        if flow_rank is not None and not flow_rank.empty:
                            # 尽量找到"主力净流入净额"列(不同版本字段名可能略有差异)
                            code_col = None
                            inflow_col = None
                            for col in flow_rank.columns:
                                cs = str(col)
                                if code_col is None and ("代码" == cs or "股票代码" in cs):
                                    code_col = col
                                if inflow_col is None and ("主力净流入" in cs and ("净额" in cs or "净额(元)" in cs or "净额(元)" in cs)):
                                    inflow_col = col
                            if code_col is None:
                                # 兜底:常见字段
                                for c in ["代码", "股票代码"]:
                                    if c in flow_rank.columns:
                                        code_col = c
                                        break
                            if inflow_col is None:
                                for c in flow_rank.columns:
                                    if "主力净流入" in str(c) and "占比" not in str(c):
                                        inflow_col = c
                                        break
                            if code_col is not None and inflow_col is not None:
                                for _, row in flow_rank.iterrows():
                                    code6 = str(row.get(code_col, "")).zfill(6)[-6:]
                                    v = row.get(inflow_col, None)
                                    try:
                                        fv = float(str(v).replace(",", ""))
                                    except Exception:
                                        continue
                                    if code6 and code6.isdigit():
                                        code_to_main_inflow[code6] = fv
                    except Exception:
                        code_to_main_inflow = {}

                    # 3) 板块成分:仅为Top5取成分股集合(避免每股都查)
                    if sector_top5_names:
                        for sec_name in sector_top5_names:
                            try:
                                cons = ak.stock_board_concept_cons_em(symbol=sec_name)
                                if cons is None or cons.empty:
                                    continue
                                # 代码列名可能为"代码"
                                codes = set()
                                if "代码" in cons.columns:
                                    for c in cons["代码"].tolist():
                                        code6 = str(c).zfill(6)[-6:]
                                        if code6.isdigit():
                                            codes.add(code6)
                                sector_to_codes[sec_name] = codes
                            except Exception:
                                continue
            except Exception:
                sector_top5_names = []
                sector_to_codes = {}
                code_to_main_inflow = {}

            def _parse_cn_money_to_yi(x):
                """把 '123.4亿' / '5600万' / 数值 转成 '亿' 为单位的 float。"""
                try:
                    if x is None:
                        return None
                    if isinstance(x, (int, float)):
                        return float(x) / 1e8
                    s = str(x).replace(",", "").strip()
                    if not s:
                        return None
                    if s.endswith("亿"):
                        return float(s[:-1])
                    if s.endswith("万"):
                        return float(s[:-1]) / 1e4
                    if s.endswith("元"):
                        return float(s[:-1]) / 1e8
                    return float(s) / 1e8
                except Exception:
                    return None

            def _tail_screen_one(code6: str, name: str):
                """
                返回 (passed:bool, detail:dict|None)
                条件:
                  - 尾盘涨幅 >2%(14:30 -> 15:00)
                  - 成交量比 >1.5(尾盘成交量 vs 全天均量(每30分钟))
                  - 股价位置:突破关键位置或创日内新高(近似:收盘接近日高/突破日高)
                  - 板块强度:所属板块涨幅前5(概念板块Top5,按成分股包含近似)
                  - 资金流向:主力资金净流入(今日主力净流入净额>0)
                  - 市值适中:50亿-500亿(优先用"流通市值",兜底"总市值")
                  - 换手率:3%-15%
                """
                try:
                    if not code6 or not str(code6).isdigit():
                        return False, None
                    code6 = str(code6).zfill(6)[-6:]

                    # 现成快照字段:最新价、最高、涨跌幅、量比、换手率、流通市值/总市值
                    spot = None
                    try:
                        spot = get_realtime_spot_row(code6)
                    except Exception:
                        spot = None

                    last_px = None
                    day_high = None
                    turnover = None
                    mktcap_yi = None
                    try:
                        if spot is not None:
                            if spot.get("最新价", None) is not None:
                                last_px = float(spot.get("最新价"))
                            if spot.get("最高", None) is not None:
                                day_high = float(spot.get("最高"))
                            # 换手率
                            for k in ("换手率", "换手", "换手率(%)"):
                                if k in spot and spot.get(k) is not None:
                                    turnover = float(str(spot.get(k)).replace("%", ""))
                                    break
                            # 市值
                            for k in ("流通市值", "总市值", "总市值(元)", "流通市值(元)"):
                                if k in spot and spot.get(k) is not None:
                                    mktcap_yi = _parse_cn_money_to_yi(spot.get(k))
                                    if mktcap_yi is not None:
                                        break
                    except Exception:
                        pass

                    # 条件:市值 50-500亿
                    if mktcap_yi is None or not (50 <= mktcap_yi <= 500):
                        return False, {
                            "code": code6, "name": name,
                            "reason": f"市值不在50-500亿({mktcap_yi if mktcap_yi is not None else '未知'}亿)"
                        }
                    # 条件:换手率 3%-15%
                    if turnover is None or not (3 <= turnover <= 15):
                        return False, {
                            "code": code6, "name": name,
                            "reason": f"换手率不在3-15%({turnover if turnover is not None else '未知'})"
                        }

                    # 条件:板块Top5(用Top5成分股包含作为近似)
                    sector_hit = None
                    if sector_top5_names and sector_to_codes:
                        for sec_name in sector_top5_names:
                            codes = sector_to_codes.get(sec_name) or set()
                            if code6 in codes:
                                sector_hit = sec_name
                                break
                    if not sector_hit:
                        return False, {
                            "code": code6, "name": name,
                            "reason": "不在概念板块涨幅前5的成分股中(近似判断)"
                        }

                    # 条件:主力资金净流入(今日)
                    main_inflow = code_to_main_inflow.get(code6)
                    if main_inflow is None:
                        return False, {"code": code6, "name": name, "reason": "无法获取主力净流入(今日)"}
                    if main_inflow <= 0:
                        return False, {"code": code6, "name": name, "reason": f"主力净流入<=0({main_inflow:,.0f}元)"}

                    # 分钟K:计算 14:30-15:00 涨幅 和 尾盘量比
                    if not AKSHARE_AVAILABLE:
                        return False, {"code": code6, "name": name, "reason": "AKShare不可用,无法计算尾盘分钟数据"}
                    import akshare as ak
                    try:
                        df1 = ak.stock_zh_a_hist_min_em(symbol=code6, period="1", adjust="")
                    except Exception:
                        df1 = None
                    if df1 is None or getattr(df1, "empty", True):
                        return False, {"code": code6, "name": name, "reason": "分钟K为空,无法计算尾盘涨幅/量比"}

                    # 兼容列名:时间/日期时间、收盘、成交量
                    time_col = None
                    close_col = None
                    vol_col = None
                    for c in df1.columns:
                        cs = str(c)
                        if time_col is None and ("时间" in cs or "日期" in cs):
                            time_col = c
                        if close_col is None and ("收盘" in cs or cs == "close"):
                            close_col = c
                        if vol_col is None and ("成交量" in cs or cs == "volume"):
                            vol_col = c
                    if time_col is None or close_col is None or vol_col is None:
                        return False, {"code": code6, "name": name, "reason": "分钟K字段缺失(时间/收盘/成交量)"}

                    def _to_hhmm(v):
                        s = str(v).strip()
                        # 可能是 '2026-03-11 14:31:00' 或 '14:31:00'
                        if " " in s:
                            s = s.split(" ")[-1]
                        if len(s) >= 5:
                            return s[:5]
                        return s

                    hhmm = df1[time_col].apply(_to_hhmm)
                    tail_mask = (hhmm >= "14:30") & (hhmm <= "15:00")
                    df_tail = df1[tail_mask]
                    if df_tail is None or df_tail.empty or len(df_tail) < 2:
                        return False, {"code": code6, "name": name, "reason": "尾盘区间数据不足(14:30-15:00)"}

                    try:
                        px_1430 = float(df_tail.iloc[0][close_col])
                        px_last = float(df_tail.iloc[-1][close_col])
                        tail_pct = (px_last - px_1430) / px_1430 * 100 if px_1430 else 0.0
                    except Exception:
                        return False, {"code": code6, "name": name, "reason": "尾盘涨幅计算失败"}

                    # 尾盘成交量 vs 全天均量(按每30分钟平均)
                    try:
                        tail_vol = float(df_tail[vol_col].astype(float).sum())
                        day_vol = float(df1[vol_col].astype(float).sum())
                        avg_30m = day_vol / 8.0 if day_vol > 0 else 0.0  # A股日内大致8个30分钟段
                        vol_ratio = (tail_vol / avg_30m) if avg_30m > 0 else 0.0
                    except Exception:
                        tail_vol = None
                        vol_ratio = 0.0

                    if not (tail_pct > 2.0):
                        return False, {"code": code6, "name": name, "reason": f"尾盘涨幅<=2%({tail_pct:.2f}%)"}
                    if not (vol_ratio > 1.5):
                        return False, {"code": code6, "name": name, "reason": f"尾盘量比<=1.5({vol_ratio:.2f})"}

                    # 股价位置:创日内新高/突破关键位(近似:现价接近日高或新高)
                    position_ok = False
                    try:
                        # 用分钟K的最高作为更准的日内高点
                        high_col = None
                        for c in df1.columns:
                            if "最高" in str(c) or str(c) == "high":
                                high_col = c
                                break
                        intraday_high = float(df1[high_col].astype(float).max()) if high_col is not None else (day_high if day_high else None)
                        if intraday_high and px_last >= intraday_high * 0.998:
                            position_ok = True
                            day_high = intraday_high
                    except Exception:
                        position_ok = False
                    if not position_ok:
                        return False, {"code": code6, "name": name, "reason": "未体现突破/日内新高(近似)"}

                    # 全部满足
                    return True, {
                        "code": code6,
                        "name": name,
                        "tail_pct": tail_pct,
                        "vol_ratio": vol_ratio,
                        "mktcap_yi": mktcap_yi,
                        "turnover": turnover,
                        "sector": sector_hit,
                        "main_inflow": main_inflow,
                        "day_high": day_high,
                    }
                except Exception as e:
                    return False, {"code": code6, "name": name, "reason": f"筛选异常: {e}"}

            for key, info in sorted_items:
                code = info.get("code") or key
                name = info.get("name") or key
                logic_sector = ""
                ma_status = None
                price_text = ""
                try:
                    # 资讯逻辑 / 板块
                    logic_list = get_stock_logic_from_db(stock_name=name) if name else []
                    if logic_list and logic_list[0].get("logic"):
                        logic_text = logic_list[0].get("logic") or ""
                        logic_sector = logic_text[:200]
                        if len(logic_text) > 200:
                            logic_sector += "..."
                    if not logic_sector and name:
                        logic_sector = get_stock_sector(name) or ""
                    # 均线状态(需要6位代码)
                    stock_code = code if code and len(str(code)) == 6 else None
                    ma_status = classify_ma_status(stock_code) if stock_code else None
                    # 实时价/当日收盘价:优先实时最新价,取不到则用最新日线收盘价
                    if not stock_code and name:
                        try:
                            sc = get_stock_code_by_name(name) or ""
                            stock_code = str(sc).zfill(6) if sc else None
                        except Exception:
                            stock_code = None
                    if stock_code:
                        rt_price = None
                        try:
                            spot_row = get_realtime_spot_row(stock_code)
                            if spot_row is not None:
                                v = spot_row.get("最新价", None)
                                if v is not None:
                                    rt_price = float(v)
                        except Exception:
                            rt_price = None
                        if rt_price is not None and rt_price > 0:
                            price_text = f" 现价:{rt_price:.2f}"
                        else:
                            try:
                                result = self._fetch_recent_daily_closes(
                                    stock_code, days=5, source="default", token=self.ts_token, return_volume=False
                                )
                                closes = result[1] if isinstance(result, tuple) and len(result) >= 2 else (result or [])
                                closes = [float(c) for c in closes if c is not None]
                                if closes:
                                    price_text = f" 收盘价:{float(closes[-1]):.2f}"
                            except Exception:
                                price_text = ""
                except Exception as e:
                    logic_sector = f"(获取失败: {e})"
                    ma_status = None

                # 尾盘选股:只对有6位代码的股票尝试,避免过慢(默认最多计算前60只)
                try:
                    code6 = str(code).zfill(6)[-6:] if code else ""
                    if len(tail_screen_hits) < 60 and code6.isdigit():
                        ok, detail = _tail_screen_one(code6, name)
                        if ok and detail:
                            tail_screen_hits.append(detail)
                except Exception:
                    pass

                results_cache.append({"logic_sector": logic_sector or "-", "ma_status": ma_status, "price_text": price_text})

            def update_ui():
                text_widget.delete("1.0", tk.END)
                text_widget.insert(tk.END, "出现次数\t来源\t代码\t名称\t逻辑/所属板块\n", "header")
                for i, (key, info) in enumerate(sorted_items):
                    code = info.get("code") or key
                    name = info.get("name") or key
                    tabs = sorted(info["tabs"])
                    tabs_str = "、".join(tabs)
                    count = info["count"]
                    rec = results_cache[i] if i < len(results_cache) else {}
                    logic_sector = rec.get("logic_sector", "-")
                    ma_status = rec.get("ma_status")
                    price_text = rec.get("price_text", "") or ""

                    # 先插入前半部分
                    prefix = f"{count}\t{tabs_str}\t{code}\t"
                    text_widget.insert(tk.END, prefix, "default")

                    # 基础颜色:龙头股+持仓 -> 红;只含龙头或日期 -> 橙;只含持仓或日期 -> 绿
                    has_leader = "龙头股" in tabs
                    has_main = "持仓" in tabs
                    if has_leader and has_main:
                        base_tag = "name_red"
                    elif has_leader:
                        base_tag = "name_orange"
                    else:
                        base_tag = "name_green"

                    # 均线结果优先覆盖基础颜色
                    if ma_status == "strong":
                        name_tag = "name_ma_strong"
                    elif ma_status == "near10":
                        name_tag = "name_ma_blue"
                    elif ma_status == "near20":
                        name_tag = "name_ma_yellow"
                    else:
                        name_tag = base_tag

                    text_widget.insert(tk.END, f"{name}{price_text}", name_tag)
                    text_widget.insert(tk.END, "\t", "default")
                    text_widget.insert(tk.END, (logic_sector or "-") + "\n", "default")

                # ===== 追加:尾盘选股(14:30-15:00) =====
                try:
                    text_widget.insert(tk.END, "\n" + "=" * 90 + "\n", "default")
                    text_widget.insert(tk.END, "尾盘选股(14:30-15:00)- 满足:尾盘涨幅>2%、尾盘量比>1.5、创日内新高/突破、板块涨幅前5、主力净流入、市值50-500亿、换手3-15%\n", "header")
                    if not tail_screen_hits:
                        text_widget.insert(tk.END, "(暂无命中;若当前非交易时段/网络慢/接口受限,分钟K或资金流可能取不到)\n", "default")
                    else:
                        # 按尾盘涨幅降序
                        hits = sorted(tail_screen_hits, key=lambda x: float(x.get("tail_pct", 0) or 0), reverse=True)[:30]
                        for h in hits:
                            text_widget.insert(
                                tk.END,
                                f"- {h.get('name','')}({h.get('code','')}) "
                                f"尾盘涨幅{float(h.get('tail_pct',0)):+.2f}% | 尾盘量比{float(h.get('vol_ratio',0)):.2f} | "
                                f"板块:{h.get('sector','')} | 主力净流入:{float(h.get('main_inflow',0)):,.0f}元 | "
                                f"市值:{float(h.get('mktcap_yi',0)):.1f}亿 | 换手:{float(h.get('turnover',0)):.2f}%\n",
                                "default",
                            )
                except Exception:
                    pass

            self.root.after(0, update_ui)

        # 先显示表格骨架,再异步填逻辑/板块
        for key, info in sorted_items:
            code = info.get("code") or key
            name = info.get("name") or key
            tabs_str = "、".join(sorted(info["tabs"]))
            text_widget.insert(
                tk.END,
                f"{info['count']}\t{tabs_str}\t{code}\t{name}\t(获取逻辑/板块中...)\n",
                "default",
            )

        def do_fetch():
            try:
                fetch_and_fill()
            except Exception:
                self.root.after(
                    0,
                    lambda: messagebox.showerror("错误", f"获取逻辑或板块失败: {e}", parent=win),
                )

        threading.Thread(target=do_fetch, daemon=True).start()

        btn_frame = ttk.Frame(top)
        btn_frame.pack(fill=tk.X)
        ttk.Button(btn_frame, text="关闭", command=win.destroy, width=10).pack(side=tk.LEFT)

    def show_backtest_dialog(self):
        """显示回测分析对话框"""
        # 创建自定义回测窗口
        custom_window = tk.Toplevel(self.root)
        custom_window.title("批量股票回测分析")
        custom_window.geometry("700x600")
        custom_window.transient(self.root)
        custom_window.grab_set()

        # 股票输入区域
        stock_frame = ttk.LabelFrame(custom_window, text="股票列表(每行一个股票名称或代码)", padding=10)
        stock_frame.pack(fill=tk.BOTH, expand=True, padx=10, pady=5)

        stock_text = scrolledtext.ScrolledText(stock_frame, height=10, wrap=tk.WORD)
        stock_text.pack(fill=tk.BOTH, expand=True)

        # 按钮区域
        stock_btn_frame = ttk.Frame(stock_frame)
        stock_btn_frame.pack(fill=tk.X, pady=(5, 0))
        ttk.Button(stock_btn_frame, text="从文件导入", command=lambda: self._import_stocks_from_file(stock_text, custom_window), width=12).pack(side=tk.LEFT, padx=2)
        ttk.Button(stock_btn_frame, text="粘贴", command=lambda: self._paste_stocks(stock_text, custom_window), width=12).pack(side=tk.LEFT, padx=2)
        ttk.Button(stock_btn_frame, text="清空", command=lambda: stock_text.delete("1.0", tk.END), width=12).pack(side=tk.LEFT, padx=2)

        # 日期设置区域
        date_frame = ttk.LabelFrame(custom_window, text="日期设置", padding=10)
        date_frame.pack(fill=tk.X, padx=10, pady=5)

        ttk.Label(date_frame, text="买入日期:").grid(row=0, column=0, padx=5, pady=5, sticky=tk.W)
        buy_date_var = tk.StringVar(value=datetime.now().strftime("%Y-%m-%d"))
        buy_date_entry = ttk.Entry(date_frame, textvariable=buy_date_var, width=12)
        buy_date_entry.grid(row=0, column=1, padx=5, pady=5)
        ttk.Button(date_frame, text="今天", command=lambda: buy_date_var.set(datetime.now().strftime("%Y-%m-%d")), width=8).grid(row=0, column=2, padx=5, pady=5)

        ttk.Label(date_frame, text="卖出日期:").grid(row=1, column=0, padx=5, pady=5, sticky=tk.W)
        sell_date_var = tk.StringVar(value="")
        sell_date_entry = ttk.Entry(date_frame, textvariable=sell_date_var, width=12)
        sell_date_entry.grid(row=1, column=1, padx=5, pady=5)
        ttk.Label(date_frame, text="(留空表示计算至今)", font=("TkDefaultFont", 8)).grid(row=1, column=2, padx=5, pady=5, sticky=tk.W)

        def start_custom_backtest():
            """开始自定义回测"""
            stock_content = stock_text.get("1.0", tk.END).strip()
            if not stock_content:
                messagebox.showwarning("警告", "请输入股票列表", parent=custom_window)
                return

            # 解析股票列表
            stock_lines = [line.strip() for line in stock_content.split('\n') if line.strip()]
            if not stock_lines:
                messagebox.showwarning("警告", "股票列表为空", parent=custom_window)
                return

            # 解析买入日期
            try:
                buy_date_str = buy_date_var.get().strip()
                buy_date = datetime.strptime(buy_date_str, "%Y-%m-%d").date()
            except:
                messagebox.showerror("错误", "买入日期格式错误,请使用 YYYY-MM-DD 格式", parent=custom_window)
                return

            # 解析卖出日期(可选)
            sell_date = None
            sell_date_str = sell_date_var.get().strip()
            if sell_date_str:
                try:
                    sell_date = datetime.strptime(sell_date_str, "%Y-%m-%d").date()
                    if sell_date < buy_date:
                        messagebox.showerror("错误", "卖出日期不能早于买入日期", parent=custom_window)
                        return
                except:
                    messagebox.showerror("错误", "卖出日期格式错误,请使用 YYYY-MM-DD 格式", parent=custom_window)
                    return

            custom_window.destroy()
            self._perform_custom_backtest(stock_lines, buy_date, sell_date)

        button_frame = ttk.Frame(custom_window)
        button_frame.pack(fill=tk.X, padx=10, pady=10)
        ttk.Button(button_frame, text="开始回测", command=start_custom_backtest, width=12).pack(side=tk.LEFT, padx=5)
        ttk.Button(button_frame, text="取消", command=custom_window.destroy, width=12).pack(side=tk.RIGHT, padx=5)

    def _import_stocks_from_file(self, text_widget, parent_window):
        """从文件导入股票"""
        filename = filedialog.askopenfilename(
            title="选择股票文件",
            filetypes=[("文本文件", "*.txt"), ("所有文件", "*.*")]
        )
        if filename:
            try:
                with open(filename, 'r', encoding='utf-8') as f:
                    content = f.read()
                text_widget.delete("1.0", tk.END)
                text_widget.insert("1.0", content)
            except Exception as e:
                messagebox.showerror("错误", f"导入失败: {e}", parent=parent_window)

    def _paste_stocks(self, text_widget, parent_window):
        """粘贴股票"""
        try:
            clipboard_text = parent_window.clipboard_get()
            text_widget.delete("1.0", tk.END)
            text_widget.insert("1.0", clipboard_text)
        except:
            messagebox.showwarning("警告", "剪贴板为空或无法获取", parent=parent_window)

    def _perform_custom_backtest(self, stock_lines, buy_date, sell_date=None):
        """执行自定义回测分析"""
        # 解析股票代码
        target_stocks = []
        STOCK_NAME_TO_CODE, STOCK_CODES_DICT, _ = load_stock_names()

        for line in stock_lines:
            stock_code = None
            stock_name = None

            # 尝试提取6位数字代码
            code_match = re.search(r'(\d{6})', line)
            if code_match:
                code = code_match.group(1)
                if code in STOCK_CODES_DICT:
                    stock_code = code
                    stock_name = STOCK_CODES_DICT[code]

            # 如果没有找到代码,尝试查找名称
            if not stock_name:
                clean_name = line.split('(')[0].strip()
                if clean_name in STOCK_NAME_TO_CODE:
                    stock_name = clean_name
                    stock_code = STOCK_NAME_TO_CODE[clean_name]
                else:
                    stock_code = get_stock_code_by_name(clean_name)
                    if stock_code:
                        stock_name = STOCK_CODES_DICT.get(stock_code, clean_name)

            if stock_code and stock_name:
                target_stocks.append((stock_name, stock_code))

        if not target_stocks:
            messagebox.showwarning("警告", "没有找到有效的股票", parent=self.root)
            return

        try:
            # 创建回测结果窗口
            backtest_result_window = tk.Toplevel(self.root)
            buy_date_str = buy_date.strftime('%Y-%m-%d')
            sell_date_str = sell_date.strftime('%Y-%m-%d') if sell_date else "至今"
            backtest_result_window.title(f"批量股票回测分析结果 - 买入日: {buy_date_str} 卖出日: {sell_date_str}")
            backtest_result_window.geometry("1000x700")

            # 确保窗口显示在最前面
            backtest_result_window.lift()
            backtest_result_window.focus_force()

            # 创建结果显示区域
            result_text_backtest = scrolledtext.ScrolledText(backtest_result_window, wrap=tk.WORD, font=("Consolas", 9))
            result_text_backtest.pack(fill=tk.BOTH, expand=True, padx=10, pady=5)

            result_text_backtest.insert("1.0", "="*100 + "\n")
            result_text_backtest.insert(tk.END, "批量股票回测分析报告\n")
            result_text_backtest.insert(tk.END, f"买入日期: {buy_date_str}\n")
            result_text_backtest.insert(tk.END, f"卖出日期: {sell_date_str}\n")
            result_text_backtest.insert(tk.END, f"回测股票数量: {len(target_stocks)}\n")
            result_text_backtest.insert(tk.END, "本金: 1000万元\n")
            result_text_backtest.insert(tk.END, f"生成时间: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}\n")
            result_text_backtest.insert(tk.END, "="*100 + "\n\n")
            result_text_backtest.insert(tk.END, "正在计算回测结果,请稍候...\n\n")
            backtest_result_window.update_idletasks()
            backtest_result_window.update()
        except Exception as e:
            import traceback
            traceback.print_exc()
            messagebox.showerror("错误", f"创建回测结果窗口失败: {e!s}", parent=self.root)
            return

        # 在后台线程中执行回测
        def custom_backtest_thread():
            try:
                backtest_results = []
                total_capital = 10000000  # 1000万

                # 更新进度信息
                def update_progress(msg):
                    try:
                        if backtest_result_window.winfo_exists():
                            result_text_backtest.insert(tk.END, f"{msg}\n")
                            result_text_backtest.see(tk.END)
                            backtest_result_window.update_idletasks()
                    except:
                        pass

                # 显示开始信息
                backtest_result_window.after(0, lambda: update_progress(f"开始回测,共 {len(target_stocks)} 只股票..."))
                time.sleep(0.1)  # 短暂延迟,确保窗口已显示

                for idx, (stock_name, stock_code) in enumerate(target_stocks, 1):
                    try:
                        # 更新进度
                        backtest_result_window.after(0, lambda n=stock_name, c=stock_code, i=idx, t=len(target_stocks): update_progress(f"[{i}/{t}] 正在计算 {n} ({c})..."))
                        if not AKSHARE_AVAILABLE:
                            continue

                        # 获取历史数据
                        hist_data = ak.stock_zh_a_hist(
                            symbol=stock_code,
                            period="daily",
                            adjust="qfq"
                        )

                        if hist_data is None or hist_data.empty:
                            continue

                        # 转换日期格式
                        hist_data['日期'] = pd.to_datetime(hist_data['日期']).dt.date

                        # 找到买入日的数据
                        buy_data = hist_data[hist_data['日期'] == buy_date]
                        if buy_data.empty:
                            # 找最近的数据
                            before_buy = hist_data[hist_data['日期'] <= buy_date]
                            if before_buy.empty:
                                continue
                            buy_data = before_buy.tail(1)

                        buy_date_actual = buy_data.iloc[0]['日期']

                        # 找到买入日次日的开盘价(买入价)
                        after_buy = hist_data[hist_data['日期'] > buy_date_actual].copy()
                        if after_buy.empty:
                            continue

                        # 买入日次日(第一个交易日)
                        next_day_data = after_buy.head(1)
                        if next_day_data.empty:
                            continue

                        next_day = next_day_data.iloc[0]['日期']
                        open_price = float(next_day_data.iloc[0]['开盘'])
                        close_price_prev = float(buy_data.iloc[0]['收盘'])

                        # 判断是否一字涨停板
                        limit_up_price = close_price_prev * 1.1
                        if open_price >= limit_up_price * 0.99:
                            continue

                        buy_price = open_price

                        # 计算卖出价
                        sell_price = None
                        sell_date_actual = None
                        profit_pct = None

                        if sell_date:
                            # 有指定卖出日期
                            sell_data = hist_data[hist_data['日期'] == sell_date]
                            if sell_data.empty:
                                # 找最近的数据
                                before_sell = hist_data[hist_data['日期'] <= sell_date]
                                if not before_sell.empty:
                                    sell_data = before_sell.tail(1)

                            if not sell_data.empty:
                                sell_date_actual = sell_data.iloc[0]['日期']
                                sell_price = float(sell_data.iloc[0]['收盘'])
                                profit_pct = ((sell_price - buy_price) / buy_price) * 100
                        else:
                            # 计算至今
                            latest_data = hist_data.tail(1)
                            if not latest_data.empty:
                                sell_date_actual = latest_data.iloc[0]['日期']
                                sell_price = float(latest_data.iloc[0]['收盘'])
                                profit_pct = ((sell_price - buy_price) / buy_price) * 100

                        if sell_price is None:
                            continue

                        backtest_data = {
                            'stock_name': stock_name,
                            'stock_code': stock_code,
                            'buy_date': next_day.strftime('%Y-%m-%d'),
                            'buy_price': buy_price,
                            'sell_date': sell_date_actual.strftime('%Y-%m-%d') if sell_date_actual else None,
                            'sell_price': sell_price,
                            'profit_pct': profit_pct,
                        }

                        backtest_results.append(backtest_data)

                    except Exception as e:
                        print(f"回测计算失败 {stock_name}: {e}")
                        import traceback
                        traceback.print_exc()
                        continue

                # 计算每只股票的买入金额和市值
                if backtest_results:
                    capital_per_stock = total_capital / len(backtest_results)

                    for r in backtest_results:
                        r['buy_amount'] = capital_per_stock
                        r['sell_value'] = capital_per_stock * (1 + r['profit_pct'] / 100)

                # 显示结果
                def display_custom_backtest_results():
                    try:
                        result_text_backtest.delete("1.0", tk.END)
                        result_text_backtest.insert("1.0", "="*100 + "\n")
                        result_text_backtest.insert(tk.END, "批量股票回测分析报告\n")
                        result_text_backtest.insert(tk.END, f"买入日期: {buy_date_str}\n")
                        result_text_backtest.insert(tk.END, f"卖出日期: {sell_date_str}\n")
                        result_text_backtest.insert(tk.END, f"回测股票数量: {len(backtest_results)}\n")
                        result_text_backtest.insert(tk.END, "本金: 1000万元\n")
                        result_text_backtest.insert(tk.END, f"生成时间: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}\n")
                        result_text_backtest.insert(tk.END, "="*100 + "\n\n")

                        if not backtest_results:
                            result_text_backtest.insert(tk.END, "没有符合条件的股票进行回测(可能都是一字涨停板买不进或数据获取失败)\n")
                            result_text_backtest.insert(tk.END, f"尝试回测的股票数量: {len(target_stocks)}\n")
                            result_text_backtest.insert(tk.END, "="*100 + "\n")
                            return

                        # 计算总体市值变化
                        total_value = sum(r['sell_value'] for r in backtest_results)
                        total_profit = total_value - total_capital
                        total_profit_pct = (total_profit / total_capital) * 100
                        capital_per_stock = total_capital / len(backtest_results)

                        result_text_backtest.insert(tk.END, "【总体市值变化统计】\n", "bold")
                        result_text_backtest.insert(tk.END, f"初始本金: {total_capital/10000:.2f}万元\n")
                        result_text_backtest.insert(tk.END, f"每只股票买入金额: {capital_per_stock/10000:.2f}万元\n\n")

                        tag = "red" if total_profit > 0 else "green"
                        result_text_backtest.insert(tk.END, f"总体市值: {total_value/10000:.2f}万元  ", tag)
                        result_text_backtest.insert(tk.END, f"盈亏: {total_profit/10000:.2f}万元 ({total_profit_pct:+.2f}%)\n", tag)

                        result_text_backtest.insert(tk.END, "\n" + "="*100 + "\n\n")
                        result_text_backtest.insert(tk.END, "【个股回测详情】\n", "bold")

                        for idx, r in enumerate(backtest_results, 1):
                            result_text_backtest.insert(tk.END, f"\n【{idx}】{r['stock_name']} ({r['stock_code']})\n", "bold")
                            result_text_backtest.insert(tk.END, f"买入日期: {r['buy_date']}  买入价: {r['buy_price']:.2f}  买入金额: {r['buy_amount']/10000:.2f}万元\n")

                            if r['sell_date']:
                                result_text_backtest.insert(tk.END, f"卖出日期: {r['sell_date']}  卖出价: {r['sell_price']:.2f}\n")
                            else:
                                result_text_backtest.insert(tk.END, f"当前日期: {r['sell_date']}  当前价: {r['sell_price']:.2f}\n")

                            tag = "red" if r['profit_pct'] > 0 else "green"
                            result_text_backtest.insert(tk.END, f"盈亏: {r['profit_pct']:.2f}%  市值: {r['sell_value']/10000:.2f}万元\n", tag)

                        result_text_backtest.insert(tk.END, "\n" + "="*100 + "\n")
                        result_text_backtest.insert(tk.END, "回测分析完成\n")

                        # 配置颜色标签
                        result_text_backtest.tag_config("red", foreground="red")
                        result_text_backtest.tag_config("green", foreground="green")
                        result_text_backtest.tag_config("bold", font=("Consolas", 9, "bold"))

                    except Exception as e:
                        import traceback
                        traceback.print_exc()
                        result_text_backtest.delete("1.0", tk.END)
                        result_text_backtest.insert("1.0", f"显示回测结果失败: {e!s}\n")

                backtest_result_window.after(0, display_custom_backtest_results)

            except Exception:
                import traceback
                traceback.print_exc()
                def show_error():
                    result_text_backtest.delete("1.0", tk.END)
                    result_text_backtest.insert("1.0", f"回测计算失败: {e!s}\n")
                    result_text_backtest.insert(tk.END, traceback.format_exc())
                backtest_result_window.after(0, show_error)

        try:
            thread = threading.Thread(target=custom_backtest_thread, daemon=True)
            thread.start()
        except Exception as e:
            import traceback
            traceback.print_exc()
            messagebox.showerror("错误", f"启动回测线程失败: {e!s}", parent=self.root)

    def show_top_list_dialog(self):
        """展示龙虎榜实时数据"""
        if not TS_AVAILABLE:
            messagebox.showerror("错误", "当前环境未安装tushare,无法获取龙虎榜数据")
            return
        if not (self.ts_token or TS_DEFAULT_TOKEN):
            messagebox.showwarning("提示", "未配置Tushare Token,无法获取龙虎榜数据")
            return

        existing = getattr(self, "_top_list_window", None)
        if existing and existing.winfo_exists():
            existing.deiconify()
            existing.lift()
            return

        win = tk.Toplevel(self.root)
        win.title("龙虎榜实时监控")
        win.geometry("1100x640")
        win.transient(self.root)

        def on_close():
            self._top_list_window = None
            win.destroy()

        win.protocol("WM_DELETE_WINDOW", on_close)
        self._top_list_window = win

        header_frame = ttk.Frame(win, padding=5)
        header_frame.pack(fill=tk.X)

        status_var = tk.StringVar(value="正在准备获取龙虎榜数据...")
        ttk.Label(header_frame, textvariable=status_var, foreground="blue").pack(side=tk.LEFT, fill=tk.X, expand=True)
        ttk.Button(header_frame, text="查看数据库", width=12,
                   command=lambda: self.show_unified_db_display(default_tab="lhb")).pack(side=tk.RIGHT, padx=(5, 0))
