        ttk.Label(date_frame, text="(格式: YYYY-MM-DD)").pack(side=tk.LEFT, padx=2)

        ttk.Label(date_frame, text="标签页名称:").pack(side=tk.LEFT, padx=(10, 5))
        tab_name_var = tk.StringVar()
