    def show_market_nav_editor(self, default_tab=None):
        """显示导航编辑窗口

        Args:
            default_tab: 默认显示的标签页索引(0=宏观&指数, 1=财经/量化平台, 2=热门榜单)
        """
        try:
            if self._nav_editor_window and self._nav_editor_window.winfo_exists():
                self._nav_editor_window.lift()
                self._nav_editor_window.focus_force()
                # 如果指定了默认标签页,切换到该标签页
                if default_tab is not None:
                    try:
                        notebook = None
                        for widget in self._nav_editor_window.winfo_children():
                            if isinstance(widget, ttk.Notebook):
                                notebook = widget
                                break
                        if notebook and default_tab < notebook.index("end"):
                            notebook.select(default_tab)
                    except Exception:
                        pass
                return
        except Exception:
            self._nav_editor_window = None

        win = tk.Toplevel(self.root)
        win.title("编辑市场指数与热点导航")
        win.geometry("780x560")
        win.transient(self.root)
        self._nav_editor_window = win

        notebook = ttk.Notebook(win)
        notebook.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)

        editor_specs = [
            ("宏观 & 指数", "indices", True),
            ("财经/量化平台", "portals", False),
            ("热门榜单", "hot_sources", False),
            ("大V公众号", "dv_accounts", True)
        ]

        for title, key, has_desc in editor_specs:
            self._create_nav_editor_tab(notebook, title, key, has_desc)

        # 如果指定了默认标签页,切换到该标签页
        if default_tab is not None and default_tab < len(editor_specs):
            notebook.select(default_tab)

        ttk.Label(
            win,
            text="提示:修改会立即保存,并刷新快速爬取界面的导航区。",
            foreground="gray"
        ).pack(fill=tk.X, padx=10, pady=(0, 10))

    def _choose_color(self, initial_color="lightgray"):
        """打开颜色选择器"""
        try:
            from tkinter import colorchooser
            color = colorchooser.askcolor(initialcolor=initial_color, title="选择颜色")
            if color and color[1]:
                return color[1]
        except Exception as e:
            print(f"打开颜色选择器失败: {e}")
        return None

    def _create_nav_editor_tab(self, notebook, title, key, has_desc):
        """创建导航编辑tab"""
        frame = ttk.Frame(notebook, padding=10)
        notebook.add(frame, text=title)

        columns = ("name", "desc", "url", "bg_color", "fg_color") if has_desc else ("name", "url", "bg_color", "fg_color")
        headings = ("名称", "描述", "链接", "背景色", "文字色") if has_desc else ("名称", "链接", "背景色", "文字色")

        tree = ttk.Treeview(frame, columns=columns, show="headings", height=10)
        tree.pack(fill=tk.BOTH, expand=True, side=tk.TOP)
        for col, heading in zip(columns, headings):
            if col == "name":
                width = 200
            elif col == "desc":
                width = 220
            elif col in ("bg_color", "fg_color"):
                width = 80
            else:
                width = 320
            tree.heading(col, text=heading)
            tree.column(col, width=width, anchor=tk.W)
        scrollbar = ttk.Scrollbar(frame, orient=tk.VERTICAL, command=tree.yview)
        tree.configure(yscrollcommand=scrollbar.set)
        scrollbar.pack(side=tk.RIGHT, fill=tk.Y)

        form_frame = ttk.LabelFrame(frame, text="编辑", padding=8)
        form_frame.pack(fill=tk.X, pady=(10, 0))

        name_var = tk.StringVar()
        desc_var = tk.StringVar()
        url_var = tk.StringVar()
        bg_color_var = tk.StringVar()
        fg_color_var = tk.StringVar()

        ttk.Label(form_frame, text="名称:").grid(row=0, column=0, sticky="e", pady=2)
        ttk.Entry(form_frame, textvariable=name_var, width=28).grid(row=0, column=1, sticky="w", pady=2, padx=(0, 8))

        current_row = 1
        if has_desc:
            ttk.Label(form_frame, text="描述:").grid(row=current_row, column=0, sticky="e", pady=2)
            ttk.Entry(form_frame, textvariable=desc_var, width=40).grid(row=current_row, column=1, sticky="w", pady=2, padx=(0, 8))
            current_row += 1

        ttk.Label(form_frame, text="链接:").grid(row=current_row, column=0, sticky="e", pady=2)
        ttk.Entry(form_frame, textvariable=url_var, width=40).grid(row=current_row, column=1, sticky="w", pady=2, padx=(0, 8))
        current_row += 1

        # 颜色选择
        color_frame = ttk.Frame(form_frame)
        color_frame.grid(row=current_row, column=0, columnspan=2, sticky="ew", pady=2)

        ttk.Label(color_frame, text="背景色:").pack(side=tk.LEFT, padx=(0, 5))
        bg_color_entry = ttk.Entry(color_frame, textvariable=bg_color_var, width=15)
        bg_color_entry.pack(side=tk.LEFT, padx=(0, 10))

        def choose_bg_color():
            color = self._choose_color(bg_color_var.get() or "lightgray")
            if color:
                bg_color_var.set(color)

        ttk.Button(color_frame, text="选择", command=choose_bg_color, width=8).pack(side=tk.LEFT, padx=(0, 20))

        ttk.Label(color_frame, text="文字色:").pack(side=tk.LEFT, padx=(0, 5))
        fg_color_entry = ttk.Entry(color_frame, textvariable=fg_color_var, width=15)
        fg_color_entry.pack(side=tk.LEFT, padx=(0, 10))

        def choose_fg_color():
            color = self._choose_color(fg_color_var.get() or "black")
            if color:
                fg_color_var.set(color)

        ttk.Button(color_frame, text="选择", command=choose_fg_color, width=8).pack(side=tk.LEFT)

        # 颜色预览
        color_preview = tk.Label(color_frame, text="预览", width=10, relief=tk.SUNKEN)
        color_preview.pack(side=tk.LEFT, padx=(20, 0))

        def update_color_preview(*args):
            bg = bg_color_var.get() or "lightgray"
            fg = fg_color_var.get() or "black"
            try:
                color_preview.config(bg=bg, fg=fg)
            except:
                pass

        bg_color_var.trace("w", update_color_preview)
        fg_color_var.trace("w", update_color_preview)
        update_color_preview()

        button_frame = ttk.Frame(form_frame)
        button_frame.grid(row=current_row + 1, column=0, columnspan=2, pady=(6, 0))

        def refresh_tree():
            tree.delete(*tree.get_children())
            data_list = self.market_nav_config.get(key, [])
            # 不要自动从默认配置加载,保持用户配置(即使是空的)
            # 如果用户需要恢复,可以使用"恢复默认"按钮
            # 按排序字段排序
            sorted_list = sorted(data_list, key=lambda x: x.get("sort_order", 999))
            for item in sorted_list:
                bg_color = item.get("bg_color", "")
                fg_color = item.get("fg_color", "")
                if has_desc:
                    values = (item.get("name", ""), item.get("desc", ""), item.get("url", ""), bg_color, fg_color)
                else:
                    values = (item.get("name", ""), item.get("url", ""), bg_color, fg_color)
                tree.insert("", tk.END, values=values)

        def clear_form():
            name_var.set("")
            desc_var.set("")
            url_var.set("")
            bg_color_var.set("")
            fg_color_var.set("")

        def get_selected_index():
            selection = tree.selection()
            if not selection:
                return None
            return tree.index(selection[0])

        def add_entry():
            name = name_var.get().strip()
            url = url_var.get().strip()
            if not name or not url:
                messagebox.showwarning("提示", "请填写名称和链接")
                return
            entry = {"name": name, "url": url}
            if has_desc:
                entry["desc"] = desc_var.get().strip()
            # 添加颜色信息
            bg_color = bg_color_var.get().strip()
            fg_color = fg_color_var.get().strip()
            if bg_color:
                entry["bg_color"] = bg_color
            if fg_color:
                entry["fg_color"] = fg_color
            # 设置排序字段(新添加的排在最后)
            data_list = self.market_nav_config.setdefault(key, [])
            entry["sort_order"] = len(data_list) + 1
            data_list.append(entry)
            self.save_market_nav_config()
            self._build_market_nav_section(self.market_nav_container)
            # 刷新合并标签页(市场指数和热点导航已合并)
            if key in ["indices", "portals", "hot_sources"]:
                self._create_merged_market_hot_tab()
            # 刷新单个配置的标签页
            if key in ["indices", "dv_accounts"]:
                self._refresh_single_config_tab(key)
            # 同时刷新整个市场导航区域
            if hasattr(self, 'market_nav_container'):
                self._build_market_nav_section(self.market_nav_container)
            refresh_tree()
            clear_form()

        def update_entry():
            idx = get_selected_index()
            if idx is None:
                messagebox.showwarning("提示", "请选择需要修改的项")
                return
            data_list = self.market_nav_config.setdefault(key, [])
            if idx >= len(data_list):
                return
            name = name_var.get().strip()
            url = url_var.get().strip()
            if not name or not url:
                messagebox.showwarning("提示", "请填写名称和链接")
                return
            data_list[idx]["name"] = name
            data_list[idx]["url"] = url
            if has_desc:
                data_list[idx]["desc"] = desc_var.get().strip()
            else:
                data_list[idx].pop("desc", None)
            # 更新颜色信息
            bg_color = bg_color_var.get().strip()
            fg_color = fg_color_var.get().strip()
            if bg_color:
                data_list[idx]["bg_color"] = bg_color
            else:
                data_list[idx].pop("bg_color", None)
            if fg_color:
                data_list[idx]["fg_color"] = fg_color
            else:
                data_list[idx].pop("fg_color", None)
            self.save_market_nav_config()
            self._build_market_nav_section(self.market_nav_container)
            # 刷新合并标签页(市场指数和热点导航已合并)
            if key in ["indices", "portals", "hot_sources"]:
                self._create_merged_market_hot_tab()
            # 刷新单个配置的标签页
            if key in ["indices", "dv_accounts"]:
                self._refresh_single_config_tab(key)
            refresh_tree()

        def delete_entry():
            idx = get_selected_index()
            if idx is None:
                messagebox.showwarning("提示", "请选择需要删除的项")
                return
            data_list = self.market_nav_config.setdefault(key, [])
            if idx >= len(data_list):
                return
            if messagebox.askyesno("确认", "确定要删除该条目吗?"):
                data_list.pop(idx)
                self.save_market_nav_config()
                self._build_market_nav_section(self.market_nav_container)
                # 刷新合并标签页(市场指数和热点导航已合并)
                if key in ["indices", "portals", "hot_sources"]:
                    self._create_merged_market_hot_tab()
                # 刷新单个配置的标签页
                if key in ["indices", "dv_accounts"]:
                    self._refresh_single_config_tab(key)
                refresh_tree()
                clear_form()

        ttk.Button(button_frame, text="新增", width=10, command=add_entry).pack(side=tk.LEFT, padx=4)
        ttk.Button(button_frame, text="更新", width=10, command=update_entry).pack(side=tk.LEFT, padx=4)
        ttk.Button(button_frame, text="删除", width=10, command=delete_entry).pack(side=tk.LEFT, padx=4)
        ttk.Button(button_frame, text="清空", width=10, command=clear_form).pack(side=tk.LEFT, padx=4)

        def on_select(event):
            selection = tree.selection()
            if not selection:
                return
            values = tree.item(selection[0], "values")
            if not values:
                return
            name_var.set(values[0])
            if has_desc:
                desc_var.set(values[1])
                url_var.set(values[2])
                bg_color_var.set(values[3] if len(values) > 3 else "")
                fg_color_var.set(values[4] if len(values) > 4 else "")
            else:
                desc_var.set("")
                url_var.set(values[1])
                bg_color_var.set(values[2] if len(values) > 2 else "")
                fg_color_var.set(values[3] if len(values) > 3 else "")

        tree.bind("<<TreeviewSelect>>", on_select)
        refresh_tree()

    def _format_ts_code(self, stock_code: str) -> str:
        """将普通股票代码转换为Tushare格式"""
        if not stock_code:
            return ""
        stock_code = stock_code.strip()
        if stock_code.startswith(("5", "6", "9")):
            suffix = "SH"
        else:
            suffix = "SZ"
        return f"{stock_code}.{suffix}"

    def _ensure_tushare_client(self, token: str = None):
        """确保Tushare客户端可用"""
        if not TS_AVAILABLE:
            raise ImportError("tushare 未安装,请先执行 pip install tushare")
        token_to_use = (token or self.ts_token or TS_DEFAULT_TOKEN).strip()
        if not token_to_use:
            raise ValueError("Tushare token 不能为空")
        if self.ts_client is None or token_to_use != self.ts_token:
            import os
            os.environ["TUSHARE_TOKEN"] = token_to_use
            self.ts_client = ts.pro_api()
            self.ts_token = token_to_use
        return self.ts_client

    def _get_stock_5day_flow_summary(self, stock_code: str) -> str:
        """获取单只股票最近5天大单/主力净资金流,返回简短描述字符串(供思维导图等使用)"""
        if not stock_code:
            return "无代码"
        try:
            net_flow_5days = None
            # 方法1: Tushare 主力资金
            if TS_AVAILABLE and (getattr(self, 'ts_token', None) or TS_DEFAULT_TOKEN):
                try:
                    if not getattr(self, 'ts_client', None):
                        self._ensure_tushare_client(self.ts_token or TS_DEFAULT_TOKEN)
                    ts_code = self._format_ts_code(stock_code)
                    end_date = datetime.now().strftime("%Y%m%d")
                    start_date = (datetime.now() - timedelta(days=30)).strftime("%Y%m%d")
                    df = self.ts_client.moneyflow(ts_code=ts_code, start_date=start_date, end_date=end_date)
                    if df is not None and not df.empty:
                        df_sorted = df.sort_values('trade_date', ascending=False).head(5)
                        if len(df_sorted) > 0:
                            if 'net_mf_amount' in df_sorted.columns:
                                net_flow_5days = float(df_sorted['net_mf_amount'].sum()) / 10000
                            elif 'net_amount' in df_sorted.columns:
                                net_flow_5days = float(df_sorted['net_amount'].sum()) / 10000
                except Exception:
                    net_flow_5days = None
            # 方法2: AKShare 历史估算
            if net_flow_5days is None and AKSHARE_AVAILABLE:
                try:
                    hist_data = ak.stock_zh_a_hist(symbol=stock_code, period="daily", adjust="qfq")
                    if hist_data is not None and not hist_data.empty and len(hist_data) >= 5:
                        if "日期" in hist_data.columns:
                            hist_data = hist_data.sort_values("日期")
                        recent_5 = hist_data.tail(5)
                        close_col = next((c for c in recent_5.columns if '收盘' in str(c) or str(c).lower() == 'close'), None)
                        vol_col = next((c for c in recent_5.columns if '成交量' in str(c) or 'volume' in str(c).lower()), None)
                        if close_col:
                            total_flow = 0
                            for i in range(1, len(recent_5)):
                                cur, prev = recent_5.iloc[i], recent_5.iloc[i-1]
                                cp, pp = float(cur[close_col]), float(prev[close_col])
                                cv = float(cur.get(vol_col, 0)) if vol_col else 0
                                chg = (cp - pp) / pp if pp > 0 else 0
                                total_flow += (cv * cp * chg * 0.3)
                            net_flow_5days = total_flow / 10000
                except Exception:
                    net_flow_5days = None
            if net_flow_5days is not None:
                return f"最近5天大单资金流: {net_flow_5days:+.2f}万元"
            return "最近5天资金流: 暂无数据"
        except Exception as e:
            return f"最近5天资金流: 获取失败({str(e)[:20]})"

    def _get_stock_5day_pct_change(self, stock_code: str) -> str:
        """获取单只股票最近5日涨跌幅(5个交易日区间),返回简短描述(供思维导图等使用)"""
        if not stock_code:
            return "无代码"
        try:
            if not AKSHARE_AVAILABLE:
                return "最近5日涨跌幅: 需akshare"
            hist_data = ak.stock_zh_a_hist(symbol=stock_code, period="daily", adjust="qfq")
            if hist_data is None or hist_data.empty or len(hist_data) < 5:
                return "最近5日涨跌幅: 暂无数据"
            if "日期" in hist_data.columns:
                hist_data = hist_data.sort_values("日期")
            else:
                hist_data = hist_data.sort_values("date") if "date" in hist_data.columns else hist_data
            recent_5 = hist_data.tail(5)
            close_col = next((c for c in recent_5.columns if '收盘' in str(c) or str(c).lower() == 'close'), None)
            if not close_col:
                return "最近5日涨跌幅: 无收盘列"
            first_close = float(recent_5.iloc[0][close_col])
            last_close = float(recent_5.iloc[-1][close_col])
            if first_close <= 0:
                return "最近5日涨跌幅: 数据异常"
            pct = (last_close - first_close) / first_close * 100
            return f"最近5日涨跌幅: {pct:+.2f}%"
        except Exception as e:
            return f"最近5日涨跌幅: 获取失败({str(e)[:15]})"

    def _get_sector_3day_flow(self, sector_name: str) -> str:
        """获取板块近3日资金流入流出,返回简短描述(供思维导图归类的板块使用)"""
        if not sector_name or sector_name == "未知板块":
            return "近3日资金流: 无板块"
        try:
            if not AKSHARE_AVAILABLE:
                return "近3日资金流: 需akshare"
            # 东方财富行业/概念资金流:先尝试 3 日,部分版本支持 indicator 参数
            for indicator in ("3日", "今日", "5日"):
                try:
                    try:
                        df = ak.stock_sector_fund_flow_rank(indicator=indicator)
                    except (TypeError, Exception):
                        df = ak.stock_sector_fund_flow_rank() if indicator == "3日" else None
                        if df is None:
                            continue
                    if df is None or df.empty:
                        continue
                    # 列名可能是 名称/板块名称/行业名称 等
                    name_col = None
                    for c in ("名称", "板块名称", "行业名称", "板块"):
                        if c in df.columns:
                            name_col = c
                            break
                    if not name_col:
                        name_col = df.columns[0]
                    net_col = None
                    for c in df.columns:
                        if "主力" in str(c) and "净" in str(c) and ("额" in str(c) or "流入" in str(c)):
                            net_col = c
                            break
                    if not net_col and "净流入" in str(df.columns.tolist()):
                        for c in df.columns:
                            if "净流入" in str(c) and "占比" not in str(c):
                                net_col = c
                                break
                    for _, row in df.iterrows():
                        sn = str(row.get(name_col, "")).strip()
                        if sn == sector_name or (sector_name in sn or sn in sector_name):
                            if net_col and net_col in row:
                                try:
                                    val = float(row[net_col])
                                    if abs(val) >= 1e8:
                                        s = f"{val/1e8:+.2f}亿"
                                    elif abs(val) >= 1e4:
                                        s = f"{val/1e4:+.2f}万"
                                    else:
                                        s = f"{val:+.2f}"
                                    return f"近3日资金流({indicator}): {s}"
                                except (TypeError, ValueError):
                                    pass
                            return f"近3日资金流({indicator}): 已找到板块"
                except Exception:
                    continue
            return "近3日资金流: 暂无数据"
        except Exception as e:
            return f"近3日资金流: 获取失败({str(e)[:20]})"

    def _get_sector_top5_leaders(self, sector_name: str) -> list:
        """获取板块前5个龙头股(按涨跌幅排序),返回 [(名称, 代码, 涨跌幅), ...]"""
        if not sector_name or sector_name == "未知板块":
            return []
        try:
            if not AKSHARE_AVAILABLE:
                return []
            cons = ak.stock_board_industry_cons_em(symbol=sector_name)
            if cons is None or cons.empty:
                return []
            # 涨跌幅列名可能是 涨跌幅/涨幅
            pct_col = None
            for c in ("涨跌幅", "涨幅", "涨跌"):
                if c in cons.columns:
                    pct_col = c
                    break
            name_col = next((c for c in ("名称", "股票名称", "简称") if c in cons.columns), cons.columns[1] if len(cons.columns) > 1 else None)
            code_col = next((c for c in ("代码", "股票代码", "序号") if c in cons.columns), cons.columns[0] if len(cons.columns) > 0 else None)
            if not pct_col or not name_col:
                return []
            cons = cons.sort_values(by=pct_col, ascending=False)
            top5 = []
            for _, row in cons.head(5).iterrows():
                try:
                    name = str(row.get(name_col, ""))
                    code = str(row.get(code_col, ""))
                    pct = row.get(pct_col, 0)
                    if isinstance(pct, (int, float)):
                        pct_str = f"{pct:+.2f}%"
                    else:
                        pct_str = str(pct)
                    top5.append((name, code, pct_str))
                except Exception:
                    continue
            return top5
        except Exception:
            return []

    def _fetch_stock_intro(self, stock_code, stock_name):
        """获取股票介绍信息(基本信息、所属板块、同板块股票)"""
        try:
            # 格式化数字为万/亿单位的辅助函数
            def format_large_number(value_str):
                """将大数字格式化为万/亿单位,保留3位小数"""
                try:
                    # 尝试转换为浮点数
                    value = float(value_str)

                    # 格式化:大于等于1亿,用亿;大于等于1万,用万;否则原样显示
                    if abs(value) >= 1e8:
                        # 转换为亿,保留3位小数
                        formatted = f"{value / 1e8:.3f}亿"
                        return formatted
                    elif abs(value) >= 1e4:
                        # 转换为万,保留3位小数
                        formatted = f"{value / 1e4:.3f}万"
                        return formatted
                    else:
                        # 小于1万的数字,如果原始值有小数则保留3位,否则显示整数
                        if value == int(value):
                            return str(int(value))
                        else:
                            return f"{value:.3f}"
                except (ValueError, TypeError):
                    # 如果无法转换为数字,返回原值
                    return value_str

            # 需要格式化的字段名(包含这些关键词的字段都会被格式化)
            numeric_fields = ['总股本', '流通股', '总市值', '流通市值', '市值', '股本',
                            '总资产', '净资产', '净利润', '营业收入', '成交额', '成交量',
                            '换手率', '市盈率', '市净率']

            result_lines = [f"股票名称: {stock_name}", f"股票代码: {stock_code}", ""]
            akshare_success = False

            # 使用akshare获取股票基本信息
            try:
                import akshare as ak
                # 获取股票基本信息
                stock_info = ak.stock_individual_info_em(symbol=stock_code)
                if stock_info is not None and not stock_info.empty:
                    result_lines.append("=== 基本信息 ===")
                    for _, row in stock_info.iterrows():
                        if len(row) >= 2:
                            key = str(row.iloc[0]).strip()
                            value = str(row.iloc[1]).strip()
                            if key and value and value != "nan":
                                # 检查是否需要格式化数字
                                need_format = any(field in key for field in numeric_fields)
                                if need_format:
                                    # 尝试提取数字部分(去除可能的单位符号)
                                    # 例如 "86139015.0" 或 "8217662031.000001"
                                    try:
                                        # 先尝试直接转换
                                        formatted_value = format_large_number(value)
                                        result_lines.append(f"{key}: {formatted_value}")
                                    except:
                                        result_lines.append(f"{key}: {value}")
                                else:
                                    result_lines.append(f"{key}: {value}")
                    result_lines.append("")
                    akshare_success = True

                # 获取所属板块
                try:
                    concept_data = ak.stock_board_concept_name_em()
                    if concept_data is not None and not concept_data.empty:
                        # 查找包含该股票的板块
                        stock_concepts = []
                        for _, row in concept_data.iterrows():
                            concept_name = str(row.get('板块名称', '')).strip()
                            if concept_name:
                                try:
                                    concept_stocks = ak.stock_board_concept_cons_em(symbol=concept_name)
                                    if concept_stocks is not None and not concept_stocks.empty:
                                        codes = concept_stocks.get('代码', [])
                                        if stock_code in [str(c).strip() for c in codes]:
                                            stock_concepts.append(concept_name)
                                except:
                                    continue

                        if stock_concepts:
                            result_lines.append("=== 所属板块 ===")
                            for concept in stock_concepts[:10]:  # 最多显示10个板块
                                result_lines.append(f"• {concept}")
                            result_lines.append("")

                            # 获取同板块股票(取第一个板块)
                            if stock_concepts:
                                try:
                                    same_concept_stocks = ak.stock_board_concept_cons_em(symbol=stock_concepts[0])
                                    if same_concept_stocks is not None and not same_concept_stocks.empty:
                                        result_lines.append(f"=== 同板块股票 ({stock_concepts[0]}) ===")
                                        for idx, (_, row) in enumerate(same_concept_stocks.iterrows()[:20]):  # 最多显示20只
                                            code = str(row.get('代码', '')).strip()
                                            name = str(row.get('名称', '')).strip()
                                            if code and name and code != stock_code:
                                                result_lines.append(f"{idx+1}. {name} ({code})")
                                        result_lines.append("")
                                except:
                                    pass
                except Exception as e:
                    result_lines.append(f"获取板块信息失败: {str(e)[:50]}")
                    result_lines.append("")
            except Exception as e:
                result_lines.append(f"获取股票信息失败: {str(e)[:50]}")

            # 如果akshare失败,尝试使用tushare
            if not akshare_success or len(result_lines) <= 3:
                try:
                    # 转换股票代码格式(tushare使用6位数字,不带前缀)
                    ts_code = stock_code
                    if '.' in stock_code:
                        ts_code = stock_code.split('.')[-1]
                    elif len(stock_code) > 6:
                        ts_code = stock_code[-6:]

                    # 确保tushare客户端可用
                    client = self._ensure_tushare_client()

                    # 获取股票基本信息
                    try:
                        stock_basic = client.stock_basic(ts_code=ts_code, fields='ts_code,symbol,name,area,industry,list_date')
                        if stock_basic is not None and not stock_basic.empty:
                            if not akshare_success:
                                result_lines = [f"股票名称: {stock_name}", f"股票代码: {stock_code}", ""]
                                result_lines.append("=== 基本信息 (Tushare) ===")
                            else:
                                result_lines.append("=== 补充信息 (Tushare) ===")

                            for _, row in stock_basic.iterrows():
                                for col in stock_basic.columns:
                                    key = col
                                    value = str(row[col]).strip()
                                    if value and value != "nan" and value != "None":
                                        # 转换字段名为中文
                                        key_map = {
                                            'ts_code': 'Tushare代码',
                                            'symbol': '股票代码',
                                            'name': '股票名称',
                                            'area': '所在地区',
                                            'industry': '所属行业',
                                            'list_date': '上市日期'
                                        }
                                        key_cn = key_map.get(key, key)
                                        result_lines.append(f"{key_cn}: {value}")
                            result_lines.append("")

                            # 获取股票概念板块
                            try:
                                concept_data = client.concept_detail(ts_code=ts_code, fields='concept_name')
                                if concept_data is not None and not concept_data.empty:
                                    concepts = concept_data['concept_name'].unique().tolist()
                                    if concepts:
                                        result_lines.append("=== 所属概念板块 (Tushare) ===")
                                        for concept in concepts[:10]:
                                            result_lines.append(f"• {concept}")
                                        result_lines.append("")
                            except:
                                pass

                            akshare_success = True  # 标记为成功
                    except Exception as e:
                        if not akshare_success:
                            result_lines.append(f"Tushare获取股票信息失败: {str(e)[:50]}")
                            result_lines.append("")
                except Exception as e:
                    if not akshare_success:
                        result_lines.append(f"Tushare初始化失败: {str(e)[:50]}")
                        result_lines.append("")

            # 如果所有数据源都失败,返回特殊标记用于网页嵌入
            if not akshare_success or len(result_lines) <= 3:
                return {"type": "web_embed", "stock_code": stock_code, "stock_name": stock_name}

            return "\n".join(result_lines) if result_lines else {"type": "web_embed", "stock_code": stock_code, "stock_name": stock_name}
        except Exception:
            return {"type": "web_embed", "stock_code": stock_code, "stock_name": stock_name}

    def _fetch_moneyflow_data(self, stock_code, stock_name):
        """获取股票大单分析数据(使用tushare的moneyflow接口)"""
        try:
            # 转换股票代码格式为tushare格式
            ts_code = stock_code
            if '.' not in stock_code:
                if len(stock_code) == 6:
                    if stock_code.startswith(('5', '6')):
                        ts_code = f"{stock_code}.SH"
                    else:
                        ts_code = f"{stock_code}.SZ"

            # 获取今日日期
            today = datetime.now().strftime('%Y%m%d')

            # 确保tushare客户端可用
            try:
                client = self._ensure_tushare_client()
            except Exception as e:
                return f"Tushare初始化失败: {e!s}\n\n请先登录Tushare"

            # 调用moneyflow接口获取最近6天的数据
            try:
                # 获取最近6个交易日的数据
                end_date = today
                start_date = (datetime.now() - timedelta(days=14)).strftime('%Y%m%d')  # 扩大范围确保能找到6个交易日
                df = client.moneyflow(ts_code=ts_code, start_date=start_date, end_date=end_date)

                if df is None or df.empty:
                        # 尝试使用akshare获取实时大单数据
                        try:
                            if AKSHARE_AVAILABLE:
                                # 尝试使用akshare获取实时资金流向数据
                                try:
                                    # 获取实时资金流向排名数据,查找目标股票
                                    money_flow_df = ak.stock_individual_fund_flow_rank(indicator="今日")
                                    if money_flow_df is not None and not money_flow_df.empty:
                                        # 查找目标股票
                                        stock_row = money_flow_df[money_flow_df['代码'] == stock_code]
                                        if not stock_row.empty:
                                            row = stock_row.iloc[0]
                                            # 提取实时大单数据
                                            buy_lg_amount_ak = float(row.get('大单净流入', 0)) / 10000  # 转换为万元
                                            buy_elg_amount_ak = float(row.get('超大单净流入', 0)) / 10000  # 转换为万元

                                            # 构建实时数据显示
                                            current_time = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
                                            result_lines_ak = [
                                                f"股票名称: {stock_name}",
                                                f"股票代码: {stock_code}",
                                                f"数据时间: {current_time}(实时数据)",
                                                "",
                                                "=" * 60,
                                                "实时大单分析(akshare数据)",
                                                "=" * 60,
                                                f"大单净流入: {buy_lg_amount_ak:,.2f} 万元",
                                                f"超大单净流入: {buy_elg_amount_ak:,.2f} 万元",
                                                f"大单+超大单净流入: {buy_lg_amount_ak + buy_elg_amount_ak:,.2f} 万元",
                                                "",
                                                "注意:此为实时数据,可能为今日累计或最近60分钟内的数据",
                                            ]

                                            # 如果有大单或超大单,用加粗红色显示
                                            if buy_lg_amount_ak != 0 or buy_elg_amount_ak != 0:
                                                result_lines_ak.append("")
                                                result_lines_ak.append("=" * 60)
                                                result_lines_ak.append("⚠️ 大单异动提示")
                                                result_lines_ak.append("=" * 60)
                                                if buy_lg_amount_ak > 0:
                                                    result_lines_ak.append(f"【大单净流入】{buy_lg_amount_ak:,.2f} 万元")
                                                if buy_elg_amount_ak > 0:
                                                    result_lines_ak.append(f"【超大单净流入】{buy_elg_amount_ak:,.2f} 万元")

                                            return "\n".join(result_lines_ak)

                                    # 如果排名数据中没有,尝试获取个股实时资金流向
                                    try:
                                        # 使用akshare的实时资金流向接口
                                        individual_flow = ak.stock_individual_fund_flow(stock=stock_code, indicator="今日")
                                        if individual_flow is not None and not individual_flow.empty:
                                            # 处理实时资金流向数据
                                            latest_row = individual_flow.iloc[-1] if len(individual_flow) > 0 else None
                                            if latest_row is not None:
                                                buy_lg_ak = float(latest_row.get('大单净流入', 0)) / 10000
                                                buy_elg_ak = float(latest_row.get('超大单净流入', 0)) / 10000

                                                current_time = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
                                                result_lines_ak = [
                                                    f"股票名称: {stock_name}",
                                                    f"股票代码: {stock_code}",
                                                    f"数据时间: {current_time}(实时数据)",
                                                    "",
                                                    "=" * 60,
                                                    "实时大单分析(akshare数据)",
                                                    "=" * 60,
                                                    f"大单净流入: {buy_lg_ak:,.2f} 万元",
                                                    f"超大单净流入: {buy_elg_ak:,.2f} 万元",
                                                    f"大单+超大单净流入: {buy_lg_ak + buy_elg_ak:,.2f} 万元",
                                                ]

                                                if buy_lg_ak != 0 or buy_elg_ak != 0:
                                                    result_lines_ak.append("")
                                                    result_lines_ak.append("⚠️ 检测到大单或超大单异动")

                                                return "\n".join(result_lines_ak)
                                    except:
                                        pass
                                except Exception:
                                    pass
                        except:
                            pass

                        return f"未获取到 {stock_name} ({stock_code}) 的大单数据\n\n可能原因:\n1. 今日非交易日\n2. 股票代码不正确\n3. Tushare积分不足(需要至少2000积分)\n4. akshare实时数据获取失败"

                # 处理多天数据:获取最近6天的数据
                if df is not None and not df.empty:
                    # 按日期排序(从新到旧,降序)
                    df = df.sort_values('trade_date', ascending=False)

                    # 取最近6条数据(最多6天,已经是按日期降序排列)
                    recent_days = df.head(6)

                    # 构建结果文本(返回结构化数据以便后续应用颜色)
                    result_data = {
                        "header": [
                            f"股票名称: {stock_name}",
                            f"股票代码: {stock_code}",
                            "数据日期范围: 最近6个交易日(从近到远)",
                            "",
                            "=" * 50,
                        ],
                        "days": []
                    }

                    # 遍历每一天的数据(从近到远)
                    for idx, row in recent_days.iterrows():
                        day_trade_date = row.get('trade_date', '')

                        # 格式化日期显示
                        if len(day_trade_date) == 8:
                            formatted_date = f"{day_trade_date[:4]}-{day_trade_date[4:6]}-{day_trade_date[6:8]}"
                        else:
                            formatted_date = day_trade_date

                        # 提取数据
                        buy_lg_amount = float(row.get('buy_lg_amount', 0))  # 大单买入金额(万元)
                        sell_lg_amount = float(row.get('sell_lg_amount', 0))  # 大单卖出金额(万元)
                        buy_elg_amount = float(row.get('buy_elg_amount', 0))  # 特大单买入金额(万元)
                        sell_elg_amount = float(row.get('sell_elg_amount', 0))  # 特大单卖出金额(万元)
                        net_mf_amount = float(row.get('net_mf_amount', 0))  # 净流入额(万元)

                        # 计算各项净流入
                        lg_net = buy_lg_amount - sell_lg_amount  # 大单净流入
                        elg_net = buy_elg_amount - sell_elg_amount  # 特大单净流入
                        total_lg_net = lg_net + elg_net  # 大单+特大单净流入(主力净额)

                        # 存储每天的数据(包含颜色信息)
                        result_data["days"].append({
                            "date": formatted_date,
                            "elg_net": elg_net,
                            "lg_net": lg_net,
                            "total_lg_net": total_lg_net,  # 主力净额
                            "net_mf_amount": net_mf_amount
                        })

                    # 返回结构化数据
                    return result_data

                # 如果没有数据,返回错误信息
                return f"未获取到 {stock_name} ({stock_code}) 的大单数据"

            except Exception as e:
                error_msg = str(e)
                if "2000" in error_msg or "积分" in error_msg:
                    return f"获取大单数据失败: Tushare积分不足\n\n需要至少2000积分才能调用moneyflow接口\n当前错误: {error_msg}"
                return f"获取大单数据失败: {error_msg}"

        except Exception as e:
            return f"获取大单分析失败: {e!s}"

    def _fetch_recent_changes(self, stock_code, stock_name):
        """获取近日涨跌幅:1.最近10日的涨跌幅(从近到远) 2.最近5日、10日、20日、60日的最高值、最低值"""
        try:
            result_lines = [f"股票名称: {stock_name}", f"股票代码: {stock_code}", ""]

            # 尝试使用akshare获取数据
            hist_data = None
            error_msgs = []

            # 方法1: 尝试使用akshare
            try:
                if AKSHARE_AVAILABLE:
                    import akshare as ak
                    # 获取历史数据
                    try:
                        hist_data = ak.stock_zh_a_hist(symbol=stock_code, period="daily", adjust="qfq")
                    except Exception as e1:
                        # 如果失败,尝试不使用qfq调整
                        try:
                            hist_data = ak.stock_zh_a_hist(symbol=stock_code, period="daily", adjust="")
                        except Exception:
                            error_msgs.append(f"akshare获取失败: {str(e1)[:50]}")
                else:
                    error_msgs.append("akshare不可用")
            except ImportError:
                error_msgs.append("akshare未安装")
            except Exception as e:
                error_msgs.append(f"akshare调用异常: {str(e)[:50]}")

            # 方法2: 如果akshare失败,尝试使用Tushare
            if (hist_data is None or hist_data.empty) and hasattr(self, '_ensure_tushare_client'):
                try:
                    client = self._ensure_tushare_client()
                    # 转换股票代码格式
                    ts_code = stock_code
                    if '.' not in stock_code:
                        if len(stock_code) == 6:
                            if stock_code.startswith(('5', '6')):
                                ts_code = f"{stock_code}.SH"
                            else:
                                ts_code = f"{stock_code}.SZ"

                    # 获取最近60天的日线数据
                    from datetime import datetime, timedelta
                    end_date = datetime.now().strftime('%Y%m%d')
                    start_date = (datetime.now() - timedelta(days=90)).strftime('%Y%m%d')

                    tushare_data = client.daily(ts_code=ts_code, start_date=start_date, end_date=end_date)
                    if tushare_data is not None and not tushare_data.empty:
                        # 转换为akshare格式的DataFrame
                        import pandas as pd
                        hist_data = pd.DataFrame({
                            '日期': tushare_data['trade_date'],
                            '收盘': tushare_data['close'],
                            '最高': tushare_data['high'],
                            '最低': tushare_data['low'],
                            '开盘': tushare_data['open'],
                            '成交量': tushare_data['vol'],
                            '成交额': tushare_data['amount']
                        })
                except Exception as e:
                    error_msgs.append(f"Tushare获取失败: {str(e)[:50]}")

            if hist_data is not None and not hist_data.empty:
                # 获取需要的列(尝试多种可能的列名)
                close_col = None
                high_col = None
                low_col = None
                date_col = None

                # 查找日期列
                for col in hist_data.columns:
                    col_str = str(col).lower()
                    if '日期' in col_str or 'date' in col_str or 'trade_date' in col_str:
                        date_col = col
                        break
                if date_col is None:
                    date_col = hist_data.columns[0]

                # 查找收盘价列
                for col in hist_data.columns:
                    col_str = str(col).lower()
                    if '收盘' in col_str or 'close' in col_str:
                        close_col = col
                        break
                if close_col is None and len(hist_data.columns) >= 2:
                    close_col = hist_data.columns[-2]  # 通常收盘价在倒数第二列

                # 查找最高价列
                for col in hist_data.columns:
                    col_str = str(col).lower()
                    if '最高' in col_str or 'high' in col_str:
                        high_col = col
                        break

                # 查找最低价列
                for col in hist_data.columns:
                    col_str = str(col).lower()
                    if '最低' in col_str or 'low' in col_str:
                        low_col = col
                        break

                if close_col is None:
                    result_lines.append("错误: 无法找到收盘价列")
                    result_lines.append(f"可用列: {', '.join(hist_data.columns.tolist())}")
                    return "\n".join(result_lines)

                if len(hist_data) > 0:
                    # 确保日期列是字符串类型,然后排序
                    try:
                        hist_data[date_col] = hist_data[date_col].astype(str)
                        # 按日期排序(从旧到新)
                        hist_data = hist_data.sort_values(date_col)
                    except Exception as e:
                        result_lines.append(f"日期排序失败: {str(e)[:50]}")
                        # 如果排序失败,直接使用原始数据

                    # 获取最近的数据(从新到旧)
                    recent_data = hist_data.tail(min(60, len(hist_data))).iloc[::-1]  # 反转,从近到远

                    # 1. 显示最近10日的涨跌幅(从近到远)
                    result_lines.append("=" * 50)
                    result_lines.append("最近10日涨跌幅(从近到远)")
                    result_lines.append("=" * 50)

                    if len(recent_data) >= 2:
                        # 获取最近10天的数据(从近到远)
                        recent_10_days = recent_data.head(10)

                        # 转换为列表以便按位置索引访问
                        recent_10_list = list(recent_10_days.iterrows())

                        for i, (idx, row) in enumerate(recent_10_list):
                            try:
                                date = str(row[date_col])
                                close_price = float(row[close_col])
                            except (ValueError, KeyError) as e:
                                result_lines.append(f"数据解析错误(第{i+1}行): {str(e)[:30]}")
                                continue

                            # 计算涨跌幅(相对于前一天)
                            # recent_data是从近到远排序的,所以i=0是最新的一天
                            # 要计算第i天的涨跌幅,需要与第i+1天(前一天)比较
                            if i < len(recent_10_list) - 1:
                                # 获取前一天的数据
                                prev_idx, prev_row = recent_10_list[i + 1]
                                prev_close = float(prev_row[close_col])
                                change_pct = ((close_price - prev_close) / prev_close) * 100
                                change_str = f"{change_pct:+.2f}%"
                            else:
                                # 如果是最后一天(最早的一天),无法计算涨跌幅
                                change_str = "--"

                            # 格式化日期显示
                            if len(date) == 10 and '-' in date:
                                formatted_date = date
                            elif len(date) == 8:
                                formatted_date = f"{date[:4]}-{date[4:6]}-{date[6:8]}"
                            else:
                                formatted_date = date

                            result_lines.append(f"{formatted_date}: 收盘价 {close_price:.2f}, 涨跌幅 {change_str}")
                    else:
                        result_lines.append("数据不足,无法显示最近10日涨跌幅")

                    # 2. 显示最近5日、10日、20日、60日的最高值、最低值
                    result_lines.append("")
                    result_lines.append("=" * 50)
                    result_lines.append("各周期最高值、最低值")
                    result_lines.append("=" * 50)

                    if high_col and low_col:
                        periods = [5, 10, 20, 60]
                        current_price = float(recent_data.iloc[0][close_col])  # 最新价格

                        for period in periods:
                            if len(recent_data) >= period:
                                # 获取最近period天的数据
                                period_data = recent_data.head(period)

                                # 计算最高值和最低值
                                high_values = period_data[high_col].astype(float)
                                low_values = period_data[low_col].astype(float)

                                max_high = high_values.max()
                                min_low = low_values.min()

                                # 计算相对于当前价格的差值
                                high_diff = current_price - max_high
                                low_diff = current_price - min_low
                                high_diff_pct = (high_diff / max_high) * 100 if max_high > 0 else 0
                                low_diff_pct = (low_diff / min_low) * 100 if min_low > 0 else 0

                                result_lines.append(f"\n最近{period}日:")
                                result_lines.append(f"  最高值: {max_high:.2f} (当前价差: {high_diff:+.2f}, {high_diff_pct:+.2f}%)")
                                result_lines.append(f"  最低值: {min_low:.2f} (当前价差: {low_diff:+.2f}, {low_diff_pct:+.2f}%)")
                            else:
                                result_lines.append(f"\n最近{period}日: 数据不足(仅{len(recent_data)}天)")
                    else:
                        result_lines.append("无法获取最高价、最低价数据")
                else:
                    result_lines.append("无法获取价格数据")
            else:
                result_lines.append("无法获取历史数据")
                if error_msgs:
                    result_lines.append("\n错误详情:")
                    for msg in error_msgs:
                        result_lines.append(f"  - {msg}")

            return "\n".join(result_lines) if result_lines else "无法获取涨跌幅信息"
        except Exception as e:
            return f"获取涨跌幅失败: {e!s}\n\n请检查:\n1. 股票代码是否正确\n2. akshare或Tushare是否可用\n3. 网络连接是否正常"

    def _fetch_history_analysis(self, stock_name):
        """获取历史涨跌分析数据(从批量分析结果表)"""
        try:
            rows = []
            try:
                conn = sqlite3.connect(DB_PATH)
                cursor = conn.cursor()
                # 查询同股票名的历史分析数据
                cursor.execute('''
                    SELECT analysis_date, high_low_days, low_diff, low_diff_pct,
                           high_diff, high_diff_pct, created_at
                    FROM batch_analysis_results
                    WHERE stock_name = ?
                    ORDER BY created_at DESC
                    LIMIT 100
                ''', (stock_name,))
                results = cursor.fetchall()
                conn.close()

                for row in results:
                    date, days, low_diff, low_diff_pct, high_diff, high_diff_pct, created_at = row
                    # 计算区间位置(如果有高低点数据)
                    if low_diff is not None and high_diff is not None:
                        # 简化计算:假设当前价在高低点中间
                        pos_ratio = 0.5
                        if high_diff != low_diff:
                            pos_ratio = abs(low_diff) / (abs(high_diff) + abs(low_diff))
                        pos_str = f"{pos_ratio * 100:.1f}%"
                    else:
                        pos_str = "--"

                    rows.append((
                        date or created_at[:10] if created_at else "--",
                        f"{days}天" if days else "--",
                        f"{low_diff:.2f}" if low_diff is not None else "--",
                        f"{low_diff_pct:+.2f}%" if low_diff_pct is not None else "--",
                        f"{high_diff:.2f}" if high_diff is not None else "--",
                        f"{high_diff_pct:+.2f}%" if high_diff_pct is not None else "--",
                        pos_str
                    ))
            except Exception as e:
                print(f"查询历史分析数据失败: {e}")

            return rows if rows else []
        except Exception as e:
            print(f"获取历史分析失败: {e}")
            return []

    def _load_managed_stocks_from_file(self):
        try:
            if os.path.exists(MANAGED_STOCKS_FILE):
                with open(MANAGED_STOCKS_FILE, "r", encoding="utf-8") as f:
                    data = json.load(f)
                if isinstance(data, list):
                    cleaned = []
                    for entry in data:
                        if isinstance(entry, dict) and entry.get("name"):
                            cleaned.append(entry)
                    self.managed_stocks = cleaned[-100:]
                    self._update_managed_stock_cache()
        except Exception as e:
            print(f"加载自选股配置失败: {e}")

    def _save_managed_stocks_to_file(self):
        try:
            os.makedirs(os.path.dirname(MANAGED_STOCKS_FILE), exist_ok=True)
            with open(MANAGED_STOCKS_FILE, "w", encoding="utf-8") as f:
                json.dump(self.managed_stocks[-100:], f, ensure_ascii=False, indent=2)
        except Exception as e:
            print(f"保存自选股配置失败: {e}")

    def _update_managed_stock_cache(self):
        names = []
        for entry in self.managed_stocks[-100:]:
            name = entry.get("name")
            if name and name not in names:
                names.append(name)
        self.managed_stock_names = names[-100:]
        self._update_waiting_combo_values()

