            ttk.Entry(meta_frame, textvariable=stock_var, width=25).grid(row=0, column=1, padx=10, pady=6, sticky=tk.W)

            ttk.Label(meta_frame, text="分析时间:", width=15).grid(row=0, column=2, padx=10, pady=6, sticky=tk.W)
