            def format_number(value, suffix=""):
                if value is None:
                    return "-"
                try:
                    return f"{float(value):.2f}{suffix}"
                except Exception:
                    return f"{value}{suffix}"

            def format_percent(value):
                if value is None:
                    return "-"
                try:
                    return f"{float(value):.2f}%"
                except Exception:
                    return "-"

            def format_market_cap(value):
                if value is None:
                    return "-"
                try:
                    val = float(value)
                    if val >= 1e8:
                        return f"{val / 1e8:.2f} 亿"
                    if val >= 1e4:
                        return f"{val / 1e4:.2f} 万"
                    return f"{val:.2f}"
                except Exception:
                    return "-"

            # 防抖处理:避免快速切换股票时频繁更新
            _update_timer = None
