                                        result_text.insert(tk.END, f"  20日均线: {ma20_status}  价格: {result['judgment_price']:.2f} >= MA20: {ma20['ma_value']:.2f}", detail_tag)
                                        result_text.insert(tk.END, f"  (差值: {ma20['diff_pct']:.2f}%)", detail_tag)
