            table_label = ttk.Label(left_content, text="股票数据列表", font=("TkDefaultFont", 10, "bold"))
            table_label.pack(anchor=tk.W, pady=(0, 5))

            table_frame = ttk.Frame(left_content)
            table_frame.pack(fill=tk.BOTH, expand=True)

