                fig = Figure(figsize=(5, 3), dpi=80)
                ax = fig.add_subplot(111)
                canvas_widget = FigureCanvasTkAgg(fig, kline_frame)
                canvas_widget.get_tk_widget().pack(fill=tk.BOTH, expand=True)

                # 显示加载中
